#!/usr/bin/env bash
# ============================================================
# PKI Script
# Author : Nicko Satria Utama
# Company: Agantra Inovatif OÜ (NextMantra)
# Email  : nicko@nextmantra.com
# Version: 7.6.6
# ============================================================
# Sign-Code.sh - sign code with a code-signing certificate (Linux build machines and pipelines).
# Bash twin of Sign-Code.ps1. Needs bash 4+, OpenSSL and curl. Manual: docs/Sign-Code-MANUAL.txt
set -u
# >>> PKI-VERSION-INFO (generated by tools/update_version_block.py - do not edit here, edit the tool source)
PKI_VER_NUMBER='7.6.6'
PKI_VER_DATE='2026-10-21'
pki_version_info() {
  # --version: the same report in every script (.ps1 and .sh). Plain text, 100 columns, no changes to the system.
  set +e +u +o pipefail 2>/dev/null
  local rule dash name uname_s kind osname osver patch arch platform id vid pretty rel maj ok
  rule="$(printf '%100s' '' | tr ' ' '=')"; dash="$(printf '%100s' '' | tr ' ' '-')"
  _row() { local label="$1" value="$2" first rest; first="${value%%$'\n'*}"; printf ' %-15s: %s\n' "$label" "$first"
           if [ "$value" != "$first" ]; then rest="${value#*$'\n'}"; printf '%s\n' "$rest" | while IFS= read -r l; do printf '%18s%s\n' '' "$l"; done; fi; }
  _run() { timeout 8 "$@" 2>&1 | tr -d '\000'; }
  _first() { printf '%s\n' "$1" | head -n1 | sed 's/[[:space:]]*$//'; }
  _find() { type -ap "$1" 2>/dev/null | awk '!s[$0]++'; }
  _key() { printf '%s\n' "$1" | sed -E 's/^([0-9]+(\.[0-9]+){0,3}).*/\1/'; }
  uname_s="${PKI_FAKE_UNAME:-$(uname -s 2>/dev/null)}"
  arch="$(uname -m 2>/dev/null)"; case "$arch" in x86_64) arch=X64 ;; aarch64|arm64) arch=Arm64 ;; i?86) arch=X86 ;; esac
  kind=other; osname="$uname_s"; osver=''; patch=''; platform='NOT supported'
  if [ "$uname_s" = Darwin ]; then
    kind=macos; osname=macOS; platform='REJECTED (macOS is not supported)'
  elif [ "$uname_s" = Linux ]; then
    kind=linux; rel="${PKI_OS_RELEASE_FILE:-/etc/os-release}"; id=''; vid=''; pretty=''
    if [ -r "$rel" ]; then id="$( . "$rel"; echo "${ID:-}")"; vid="$( . "$rel"; echo "${VERSION_ID:-}")"; pretty="$( . "$rel"; echo "${PRETTY_NAME:-}")"; fi
    osname="${pretty:-Linux}"; osver="$vid"; patch="kernel $(uname -r 2>/dev/null)"
    maj="${vid%%.*}"; case "$maj" in ''|*[!0-9]*) maj=0 ;; esac; ok=0
    case "$id" in ubuntu) [ "$maj" -ge 24 ] && ok=1 ;; centos|rhel|rocky|ol) [ "$maj" -ge 10 ] && ok=1 ;; sles|sles_sap|sled|opensuse-leap) [ "$maj" -ge 15 ] && ok=1 ;; opensuse-tumbleweed) ok=1 ;; esac
    if [ "$ok" = 1 ]; then platform='supported: full (Classic and Quantum)'; else platform='NOT supported (see the platform list in the manual)'; fi
  fi
  name="$(basename "$0")"
  echo "$rule"; echo " $name  -  version information"; echo "$rule"
  echo ' SCRIPT'
  _row Name "$name"
  _row Version "$PKI_VER_NUMBER   (build of $PKI_VER_DATE)"
  _row Author 'Nicko Satria Utama'
  _row Company 'Agantra Inovatif OÜ (NextMantra)'
  _row Email 'nicko@nextmantra.com'
  echo "$dash"; echo ' OPERATING SYSTEM'
  _row Name "$osname"
  [ -n "$osver" ] && _row Version "$osver"
  [ -n "$patch" ] && _row Patch/kernel "$patch"
  [ -n "$arch" ] && _row Architecture "$arch"
  _row Platform "$platform"
  if [ "$kind" = macos ]; then echo "$dash"; echo ' macOS is rejected by these scripts. Nothing else is checked.'; echo "$rule"; return 5; fi

  echo "$dash"; echo ' .NET'
  local dn sdks rts first rest
  dn="$(_find dotnet | head -n1)"
  if [ -n "$dn" ]; then
    sdks="$(_run "$dn" --list-sdks | awk '/^[0-9]+\.[0-9]+\.[0-9]+/ {print $1}' | sort -rV)"
    rts="$(_run "$dn" --list-runtimes | awk '/^Microsoft\./ {sub(/^Microsoft\./,"",$1); print $1, $2}' | sort -k1,1 -k2,2Vr | awk '!s[$1]++ {print $1" "$2}')"
    if [ -n "$sdks" ]; then first="$(printf '%s\n' "$sdks" | head -n1)"; rest="$(printf '%s\n' "$sdks" | tail -n +2 | paste -sd, - | sed 's/,/, /g')"
      if [ -n "$rest" ]; then _row 'SDK (latest)' "$first   (also $rest)"; else _row 'SDK (latest)' "$first"; fi
    else _row 'SDK (latest)' 'none installed'; fi
    if [ -n "$rts" ]; then _row Runtime "$rts"; else _row Runtime 'none installed'; fi
  else _row 'SDK (latest)' 'not found'; _row Runtime 'not found'; fi
  _row Framework 'n/a (Windows only)'

  echo "$dash"; echo ' NODE.JS, PYTHON 3, JAVA'
  local nd nv py pp p t jv jt jver jven jc jct
  nd="$(_find node | head -n1)"; nv=''; [ -n "$nd" ] && nv="$(_first "$(_run "$nd" --version)")"
  if printf '%s' "$nv" | grep -Eq '^v?[0-9]+\.[0-9]+\.[0-9]+'; then _row Node.js "$(printf '%s' "$nv" | sed -E 's/^v?([0-9]+\.[0-9]+\.[0-9]+).*/\1/')   $nd"; else _row Node.js 'not found'; fi
  py=''; pp=''
  for c in python3 python; do for p in $(_find $c); do t="$(_first "$(_run "$p" --version)")"; if printf '%s' "$t" | grep -Eq '^Python 3\.[0-9]+'; then py="${t#Python }"; pp="$p"; break; fi; done; [ -n "$py" ] && break; done
  if [ -n "$py" ]; then _row 'Python 3' "$py   $pp"; else _row 'Python 3' 'not found'; fi
  jv="$(_find java | head -n1)"; jt=''; [ -n "$jv" ] && jt="$(_run "$jv" -XshowSettings:properties -version)"
  if printf '%s' "$jt" | grep -Eq 'version "[^"]+"'; then
    jver="$(printf '%s\n' "$jt" | sed -nE 's/.*version "([^"]+)".*/\1/p' | head -n1)"; jven="$(printf '%s\n' "$jt" | sed -nE 's/^ *java\.vendor = (.+)$/\1/p' | head -n1 | sed 's/[[:space:]]*$//')"
    if [ -n "$jven" ]; then _row 'Java runtime' "$jver   $jven"; else _row 'Java runtime' "$jver"; fi
  else _row 'Java runtime' 'not found'; fi
  jc="$(_find javac | head -n1)"; jct=''; [ -n "$jc" ] && jct="$(_run "$jc" -version | grep -m1 '^javac ')"
  if printf '%s' "$jct" | grep -Eq '^javac '; then _row 'JDK (javac)' "${jct#javac }"; else _row 'JDK (javac)' 'not found'; fi

  echo "$dash"; echo ' SHELLS'
  local pl psl bs bt oth f s
  pl=''; for p in $(_find pwsh); do t="$(_run "$p" -NoProfile -Command '$PSVersionTable.PSVersion.ToString()')"; t="$(_first "$t")"; printf '%s' "$t" | grep -Eq '^[0-9]+\.[0-9]+' && pl="$pl$t"$'\n'; done
  psl="$(printf '%s' "$pl" | awk 'NF && !s[$0]++' | sort -V | paste -sd, - | sed 's/,/, /g')"
  if [ -n "$psl" ]; then _row PowerShell "$psl"; else _row PowerShell 'not found'; fi
  bs="$(_find bash | head -n1)"; bt=''; [ -n "$bs" ] && bt="$(_first "$(_run "$bs" --version)")"
  if printf '%s' "$bt" | grep -Eq 'version [0-9]'; then _row Bash "$(printf '%s' "$bt" | sed -E 's/.*version ([^ ]+).*/\1/')   $bs"; else _row Bash 'not found'; fi
  oth=''
  for s in zsh fish tcsh ksh dash csh; do
    f="$(_find $s | head -n1)"; [ -z "$f" ] && continue
    [ "$s" = csh ] && printf '%s' "$oth" | grep -q 'tcsh' && continue
    t=''; case "$s" in zsh|fish|tcsh) t="$(_first "$(_run "$f" --version)")" ;; esac
    if printf '%s' "$t" | grep -Eq '[0-9]+\.[0-9]+'; then oth="$oth$s $(printf '%s' "$t" | grep -Eo '[0-9]+\.[0-9]+(\.[0-9]+)*' | head -n1), "; else oth="$oth$s (present), "; fi
  done
  oth="${oth%, }"; if [ -n "$oth" ]; then _row 'Other shells' "$oth"; else _row 'Other shells' 'none found'; fi

  echo "$dash"; echo ' TLS: SCHANNEL AND OPENSSL'
  _row Schannel 'n/a (Windows only)'
  local cands npath known g cfg sdir sec l real pre ld ver lib vendor own role idx rows seen ok4 line
  cands="$(_find openssl)"; npath=$(printf '%s\n' "$cands" | grep -c .)
  known=''; for g in /usr/bin/openssl /usr/local/bin/openssl /usr/local/ssl/bin/openssl /opt/openssl*/bin/openssl /opt/*/bin/openssl /usr/local/openssl*/bin/openssl; do for f in $g; do [ -x "$f" ] && known="$known$f"$'\n'; done; done
  sdir="$(cd "$(dirname "$0")" 2>/dev/null && pwd)"; cfg="$sdir/pki_tools.cnf"
  if [ -r "$cfg" ]; then known="$known$(awk '/^[ \t]*\[/ {sec=$0; gsub(/[ \t\[\]]/,"",sec)} sec=="openssl" && /^[ \t]*Path[ \t]*=/ {sub(/^[^=]*=[ \t]*/,""); sub(/[ \t]+$/,""); print}' "$cfg" | while IFS= read -r l; do [ -x "$l" ] && echo "$l"; done)"$'\n'; fi
  cands="$(printf '%s\n%s\n' "$cands" "$known" | grep .)"
  seen=''; rows=0; idx=0; ok4=0
  while IFS= read -r p; do
    [ -z "$p" ] && continue
    real="$(readlink -f "$p" 2>/dev/null)"; [ -z "$real" ] && real="$p"
    case "$seen" in *"|$real|"*) idx=$((idx+1)); continue ;; esac; seen="$seen|$real|"
    ld=''; pre="$(dirname "$(dirname "$real")")"; [ -n "$pre" ] && [ "$pre" != /usr ] && ld="$pre/lib64:$pre/lib"
    t="$(LD_LIBRARY_PATH="${ld}${ld:+:}${LD_LIBRARY_PATH:-}" _run "$real" version)"
    if ! printf '%s' "$t" | grep -Eq '(OpenSSL|LibreSSL) [0-9]+\.[0-9]+\.[0-9]+'; then idx=$((idx+1)); continue; fi
    lib="$(printf '%s' "$t" | grep -Eo '(OpenSSL|LibreSSL) [0-9]+\.[0-9]+\.[0-9]+[^ ]*' | head -n1)"; ver="${lib#* }"; lib="${lib%% *}"
    if [ "$lib" = LibreSSL ]; then vendor='LibreSSL project'
    else
      own="$(_first "$(dpkg -S "$real" 2>/dev/null)")"
      if printf '%s' "$own" | grep -Eq '^[a-z0-9][A-Za-z0-9.+_-]*(:[a-z0-9]+)?: /'; then vendor="package $(printf '%s' "$own" | sed -E 's/^([^:]+).*/\1/') (dpkg)"
      else own="$(_first "$(rpm -qf "$real" 2>/dev/null)")"
        if [ -n "$own" ] && ! printf '%s' "$own" | grep -Eqi 'not owned|error|No such'; then vendor="package $own (rpm)"; else vendor='built from source code (openssl.org), not a package'; fi
      fi
    fi
    if [ "$rows" = 0 ] && [ "$idx" -lt "$npath" ]; then role=Default; else role=Side; fi
    _row "$role OpenSSL" "$ver   $real"$'\n'"from: $vendor"
    printf '%s' "$ver" | grep -Eq '^[4-9]\.' && ok4=1
    rows=$((rows+1)); idx=$((idx+1))
  done <<< "$cands"
  if [ "$rows" = 0 ]; then _row OpenSSL 'not found'
  elif [ "$ok4" = 1 ]; then _row 'PKI needs' 'OpenSSL 4.x: found'
  else _row 'PKI needs' 'OpenSSL 4.x: NOT found (Install-DevEnvironment can install it)'; fi
  echo "$rule"
  return 0
}
for __pki_a in "$@"; do case "$__pki_a" in --version) pki_version_info; exit $? ;; esac; done
# <<< PKI-VERSION-INFO
if [ "${BASH_VERSINFO[0]:-0}" -lt 4 ]; then echo "[ERROR] bash 4 or newer is needed." >&2; exit 1; fi
VERSION=7.6.6
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

help_pager() {  # help text: one screen at a time on a terminal (Space = next page, q = quit); everything when piped
  if [ -t 1 ] && command -v less >/dev/null 2>&1; then less -FRXK; elif [ -t 1 ] && command -v more >/dev/null 2>&1; then more; else cat; fi
}
show_help() {
cat <<'HELP_EOF'
====================================================================================================
 Sign-Code.sh  -  sign your code with a code-signing certificate (Linux)
 Version 7.6.6
 Author : Nicko Satria Utama
 Company: Agantra Inovatif OÜ (NextMantra)
 Email  : nicko@nextmantra.com
====================================================================================================
 On a terminal: SPACE = next page, ENTER = next line, Q = quit.
 Manual : docs/Sign-Code-MANUAL.txt                       Windows twin: Sign-Code.ps1
 Runs on: Ubuntu 24.04+, CentOS Stream 10, RHEL 10, Rocky Linux 10, Oracle Linux 10 (bash 4+).
          By hand, or on a build agent: GitHub Actions (ubuntu), Azure DevOps Services (cloud) and
          Azure DevOps Server (on premises, Linux agent), GitLab CI/CD, Jenkins, Bitbucket,
          TeamCity, AWS CodeBuild, Alibaba Cloud Yunxiao Flow, Google Cloud Build, dotnet build
          (MSBuild Exec), and any Linux container or VM.

WHAT IT IS
  Code signing puts your name on a program, so people can see who made it and that nobody changed
  it. This script does the whole job in a safe order:
  1. Reads the code-signing certificate and CHECKS it. A certificate that breaks the rules is
     REFUSED before any file is touched (exit 2).
  2. CHECKS the timestamp server. It must answer, and its own certificate must be valid (exit 3).
  3. Finds the tools it needs. A missing tool is INSTALLED from the package manager (apt or dnf),
     from a PPA / COPR you name, or (Jsign) from Maven Central.
  4. Signs every file you listed, and every supported file in the folders you listed.
  5. Verifies each signature, writes <file>-signed.sha256 and <file>-signed.sha512 next to it and
     prints the certificate.

QUICK START
  0. With the certificates of GenerateCodeSigningCertificate.sh / .ps1 (the right one per file):
        ./Sign-Code.sh --use-generated --folder ./publish --verbose
  1. Check only. Nothing is signed:     ./Sign-Code.sh --pfx codesign.pfx --check-only
  2. Sign three files:
        ./Sign-Code.sh --pfx codesign.pfx --file app.dll --file tool.jar --file app.apk
  3. Sign a whole publish folder:       ./Sign-Code.sh --pfx codesign.pfx --folder ./publish
  The PFX password comes from the variable SIGN_PFX_PASSWORD. Not set + a terminal = you are asked.
  Never write a password on the command line.

THE FILES
  --file <path>         One file. Repeat it:  --file app.dll --file tool.jar
  --folder <path>       One folder, with its sub-folders. Repeat it.
  --no-recurse          Do not go into sub-folders.
  --include <glob> / --exclude <glob>   Wildcards on the file name (repeatable), e.g.
                        --exclude '*.Tests.dll'
  --out-folder <path>   Sign COPIES in this folder. The originals stay untouched. Default: in place.
  --skip-signed         Accepted so the command line is the same as Sign-Code.ps1.
  Supported on Linux:
    Windows files  exe dll sys ocx scr cpl efi msi cab cat msix appx          (osslsigncode)
    PowerShell     ps1 psm1 psd1 ps1xml psc1 cdxml                            (osslsigncode)
    .NET           dll / exe of .NET apps = the Windows files above; NuGet nupkg snupkg (dotnet)
    Java           jar war ear (jarsigner)          Android   apk (apksigner), aab (jarsigner)
    Apple          Mach-O (no extension, found by its first bytes), dylib, bundles .app .framework
                   .appex .xpc .kext .plugin .bundle (a FOLDER, signed as one item), dmg, pkg
                   (rcodesign; installed with cargo when missing). Timestamp: Apple's server unless
                   --timestamp / --timestamp-url is given. Gatekeeper also needs notarization.
  Skipped with a message: MS Office VBA, vbs, js, wsf (need Windows). Linux packages (rpm, deb,
  ELF): use GPG / rpm --addsign.

THE CERTIFICATE  (choose ONE way)
  --use-generated            The certificates of GenerateCodeSigningCertificate.sh / .ps1: reads
                             leafcerts/codesign/codesign-index.tsv and takes, per file, the newest
                             valid certificate of its platform (windows, java, android, apple,
                             apple-installer for .pkg) and its chain. Password: SIGN_PFX_PASSWORD,
                             not set = the generator default Abc12345!.
    --generated-root <dir>   Another leafcerts/codesign folder.
    --generated-platform <p> windows | java | android | apple | apple-installer for all files.
  --pfx <file>               A .pfx / .p12 file. Password: the variable named by --pfx-password-env
                             (default SIGN_PFX_PASSWORD).
  --cert-folder <dir>        A local folder with the certificate (e.g. leafcerts/codesign/<co>/java):
                             its newest .pfx, and <name>-chain.crt for the chain check.
  --pfx-base64-env <name>    Name of a variable (a pipeline SECRET) that holds the .pfx as base64.
                             Written to a temporary file, deleted at the end.
  --cert-pem <file> --key-pem <file>
                             Your private PKI leaf as PEM files (GenerateLeafCertificate
                             --purpose CodeSigning). Key password: variable --key-password-env.
  --provider <name>          The key lives in a cloud / HSM service (best for
                             pipelines). Give details with --provider-arg:
                               azurekeyvault         Jsign  "vault-name|cert-name"
                               azuretrustedsigning   Jsign  "endpoint-host|account/profile"
                               awskms                Jsign  "region|key-alias"
                               gcpkms                Jsign  "keyring-path|key-alias"
                               pkcs11                Jsign  "pkcs11.cfg|alias"
                                                          (PIN: SIGN_PKCS11_PIN)
                               digicertkeylocker     smctl  "key-pair-alias"
                             Tokens come from the cloud CLI (az, gcloud) or the usual variables
                             (AWS_ACCESS_KEY_ID ...) and are passed through a variable.
  --cert-file <file>         With --provider: the PUBLIC certificate (PEM), so checks can run.
  --cert-source <x>          privatepki | publicca | auto (default). auto = publicca when the chain
                             ends at a root of this computer's trust store. publicca is stricter
                             (RSA 3072+).
  --chain-file <file>        CA certificates of your private PKI (ca-bundle.pem) to check the chain.
  --trust-store <file>|system   The roots the chain is checked against, with --chain-file. Default
                             system: the ca-certificates bundle (/etc/ssl/certs/ca-certificates.crt,
                             /etc/pki/tls/certs/ca-bundle.crt). A private root put there with
                             update-ca-certificates / update-ca-trust (Install-PkiTrust.sh) is
                             trusted. The key itself never comes from ca-certificates.

TIMESTAMP  (without one the signature dies when the certificate expires: always use one)
  --timestamp <name>         digicert (default), globalsign, certum, sectigo, sslcom, entrust,
                             microsoft, apple, identrust, quovadis, swisssign, buypass, harica,
                             freetsa, or a URL.
  --timestamp-url <url>      Any RFC 3161 server address (your own TSA too). It wins over --timestamp.
  --timestamp-fallback       The server fails its check: try digicert, sectigo, globalsign, sslcom,
                             certum, entrust, microsoft in that order (good for pipelines).
  --digest sha256|sha384|sha512     File and timestamp digest. Default sha256.

INSTALLING TOOLS
  --installer auto|none      auto (default): apt on Ubuntu, dnf on CentOS Stream / RHEL / Rocky /
                             Oracle. none: install nothing.
  --ppa ppa:owner/name       Ubuntu: add this PPA first. (dotnet falls back to
                             ppa:dotnet/backports.)
  --copr owner/project       RHEL family: enable this COPR first.
  osslsigncode on the RHEL family comes from EPEL. It is enabled for you (CentOS Stream and Rocky:
  crb + epel-release; Oracle: oracle-epel-release-el10).

OTHER
  --description <text> --description-url <url>   Shown to people who open the signature details.
  --check-only          Run the certificate and timestamp checks, then stop.
  --show-certificate    Print the certificate (also printed after signing).
  --strict              A skipped or failed file fails the whole run (exit 6).
  --ci                  Pipeline mode: no questions, a summary, every temporary secret file removed
                        at the end. Switched on by itself on a known build agent. Warnings and
                        errors become annotations: GitHub Actions, Azure DevOps Services and
                        Server, TeamCity, MSBuild. Detected: GitHub, Azure DevOps Services /
                        Server, GitLab, Jenkins, TeamCity, Bitbucket, AWS CodeBuild, Google Cloud.
  --verbose, -v         Show every step and every command line (passwords shown as ***) and the
                        output of the signing tools.
  --template github|azure|azure-server|gitlab|jenkins|bitbucket|teamcity|aws|gcp|alibaba|msbuild|all
                        Write ready-to-edit pipeline files into transport/signing-ci_<time>/, stop.
  --help                this text
  --version             show version, author, OS and tool versions.

BUILD AGENT SETUP  (DevSecOps)
  The agent needs bash 4+, openssl and curl (hosted Ubuntu images have them), outbound HTTP (port
  80) to the timestamp server, and HTTPS to the package sources. On a locked-down agent put the
  tools in the image, add --installer none and use your own server with --timestamp-url.
  Secrets: never in the repository, never on the command line.
    Private PKI leaf   store the .pfx as BASE64 in one secret and its password in a second one.
                       Map both to variables, then use  --ci --pfx-base64-env <NAME>.
                       Make the base64:  base64 -w0 codesign.pfx
    Public OV / EV     the key must be in hardware: use --provider. The key never reaches the agent.
    Cloud login        use the identity of the pipeline (OIDC, managed identity), not a password.
  Steps: 1) run --ci --check-only once to prove secret, certificate and timestamp.  2) Put the real
  step AFTER the build and BEFORE publishing.  3) Sign what you ship, not obj/ or test files:
  --folder <publish folder> --exclude '*.Tests.dll'.  4) Any result other than 0 stops the pipeline.
  Keep sign-report_*.json and the *-signed.sha256 / .sha512 files as proof.

EXAMPLES
  ./Sign-Code.sh --pfx codesign.pfx --file app.dll --file tool.jar --file app.apk
  ./Sign-Code.sh --cert-pem cs.crt --key-pem cs.key --chain-file ca-bundle.pem --folder /b/a \
        --folder /b/b
  ./Sign-Code.sh --timestamp globalsign --pfx codesign.pfx --folder ./publish \
        --exclude '*.Tests.dll'
  ./Sign-Code.sh --ci --provider awskms --provider-arg "eu-central-1|alias/codesign" \
        --cert-file cs.crt --folder out
  ./Sign-Code.sh --use-generated --file app.dll --file tool.jar --file app.apk --verbose
  ./Sign-Code.sh --cert-folder leafcerts/codesign/Agantra_Inovatif_OU/java --folder ./publish
  ./Sign-Code.sh --pfx codesign.pfx --file MyApp.app --file MyApp.dmg --timestamp apple
  ./Sign-Code.sh --template all

EXIT CODES  0 ok   1 error   2 certificate refused   3 timestamp server failed
            4 tool missing / install failed   5 wrong platform   6 some files skipped or failed
            7 no file to sign
====================================================================================================
HELP_EOF
}
template_text() {
  case "$1" in
    github-actions.yml)
cat <<'TPL_EOF'
# GitHub Actions: sign after the build. Secrets: SIGN_PFX_B64 (the .pfx as base64) and SIGN_PFX_PASSWORD.
# Public OV/EV certificates: use a cloud signing service (see the manual) instead of a .pfx secret.
name: build-and-sign
on: [push]
jobs:
  build:
    runs-on: windows-latest          # Windows Server 2025 image; use ubuntu-latest + Sign-Code.sh for Linux
    steps:
      - uses: actions/checkout@v4
      - uses: actions/setup-dotnet@v4
        with: { dotnet-version: '9.0.x' }
      - run: dotnet build -c Release -o out
      - name: Sign
        shell: pwsh
        env:
          SIGN_PFX_B64: ${{ secrets.SIGN_PFX_B64 }}
          SIGN_PFX_PASSWORD: ${{ secrets.SIGN_PFX_PASSWORD }}
        run: ./Sign-Code.ps1 -Ci -PfxBase64Env SIGN_PFX_B64 -Folder out -Timestamp DigiCert
      - uses: actions/upload-artifact@v4
        with: { name: signed, path: out }
TPL_EOF
;;
    azure-pipelines.yml)
cat <<'TPL_EOF'
# Azure DevOps Services (cloud, dev.azure.com). Library variables: SIGN_PFX_B64, SIGN_PFX_PASSWORD (mark them secret).
# Azure DevOps Server (on premises): see azure-devops-server-pipelines.yml.
# A secret variable is NOT visible to a script by itself: map it with env: as shown.
trigger: [ main ]
pool: { vmImage: windows-latest }      # self-hosted agent: Windows 11 / Server 2022 / 2025 with PowerShell 7
steps:
  - task: UseDotNet@2
    inputs: { version: 9.x }
  - script: dotnet build -c Release -o $(Build.ArtifactStagingDirectory)\out
  - pwsh: ./Sign-Code.ps1 -Ci -PfxBase64Env SIGN_PFX_B64 -Folder "$(Build.ArtifactStagingDirectory)\out"
    displayName: Sign code
    env:
      SIGN_PFX_B64: $(SIGN_PFX_B64)
      SIGN_PFX_PASSWORD: $(SIGN_PFX_PASSWORD)
  # Key in Azure Key Vault instead (no secret in the pipeline, use a service connection / managed identity):
  # - pwsh: ./Sign-Code.ps1 -Ci -Provider AzureKeyVault -ProviderArg "https://myvault.vault.azure.net|codesign" -CertFile codesign.cer -Folder out
  - publish: $(Build.ArtifactStagingDirectory)\out
    artifact: signed
TPL_EOF
;;
    azure-devops-server-pipelines.yml)
cat <<'TPL_EOF'
# Azure DevOps Server 2022 / 2025 (on premises). The agent is YOURS: a self-hosted Windows agent with PowerShell 7.
# Library variables SIGN_PFX_B64 / SIGN_PFX_PASSWORD (secret), or the certificate already in the agent's store
# (LocalMachine\My, imported by GenerateCodeSigningCertificate.ps1 -InstallPfx -InstallStore LocalMachine).
trigger: [ main ]
pool: { name: Default, demands: [ Agent.OS -equals Windows_NT ] }    # your agent pool
steps:
  - script: dotnet build -c Release -o $(Build.ArtifactStagingDirectory)\out
  - pwsh: ./Sign-Code.ps1 -Ci -PfxBase64Env SIGN_PFX_B64 -Folder "$(Build.ArtifactStagingDirectory)\out" -Timestamp DigiCert -TimestampFallback
    displayName: Sign code (PFX secret)
    env:
      SIGN_PFX_B64: $(SIGN_PFX_B64)
      SIGN_PFX_PASSWORD: $(SIGN_PFX_PASSWORD)
  # Certificate in the agent's Windows store (no secret in the pipeline):
  # - pwsh: ./Sign-Code.ps1 -Ci -Subject "CN=Agantra Inovatif OU" -StoreLocation LocalMachine -Folder "$(Build.ArtifactStagingDirectory)\out"
  # No internet on the agent: your own RFC 3161 server with -TimestampUrl http://tsa.example.local
  - task: PublishBuildArtifacts@1
    inputs: { PathtoPublish: $(Build.ArtifactStagingDirectory)\out, ArtifactName: signed }
TPL_EOF
;;
    gitlab-ci.yml)
cat <<'TPL_EOF'
# GitLab CI/CD (gitlab.com or self-managed). Settings > CI/CD > Variables: SIGN_PFX_B64 (masked, protected) and
# SIGN_PFX_PASSWORD (masked, protected). Rename to .gitlab-ci.yml or include it.
stages: [ build, sign ]
build:
  stage: build
  image: mcr.microsoft.com/dotnet/sdk:9.0
  script: [ dotnet build -c Release -o out ]
  artifacts: { paths: [ out/ ] }
sign-linux:                       # jar, apk, Windows files (osslsigncode / jsign), Apple (rcodesign)
  stage: sign
  image: ubuntu:24.04
  script:
    - bash ./Sign-Code.sh --ci --pfx-base64-env SIGN_PFX_B64 --folder out --timestamp digicert --timestamp-fallback
  artifacts: { paths: [ out/ ] }
# Windows runner (tag windows) for signtool / PowerShell scripts / MSI:
# sign-windows:
#   stage: sign
#   tags: [ windows ]
#   script: [ pwsh -File ./Sign-Code.ps1 -Ci -PfxBase64Env SIGN_PFX_B64 -Folder out ]
TPL_EOF
;;
    Jenkinsfile)
cat <<'TPL_EOF'
// Jenkins (declarative pipeline). Credentials: a "Secret file" sign-pfx (the .pfx) and a "Secret text" sign-pfx-password.
pipeline {
  agent { label 'windows' }               // or 'linux' with Sign-Code.sh
  stages {
    stage('Build') { steps { pwsh 'dotnet build -c Release -o out' } }
    stage('Sign') {
      steps {
        withCredentials([file(credentialsId: 'sign-pfx', variable: 'SIGN_PFX_FILE'),
                         string(credentialsId: 'sign-pfx-password', variable: 'SIGN_PFX_PASSWORD')]) {
          pwsh './Sign-Code.ps1 -Ci -Pfx $env:SIGN_PFX_FILE -Folder out -Timestamp DigiCert'
          // Linux agent: sh 'bash ./Sign-Code.sh --ci --pfx "$SIGN_PFX_FILE" --folder out'
        }
      }
    }
  }
  post { success { archiveArtifacts artifacts: 'out/**' } }
}
TPL_EOF
;;
    bitbucket-pipelines.yml)
cat <<'TPL_EOF'
# Bitbucket Pipelines. Repository variables (secured): SIGN_PFX_B64, SIGN_PFX_PASSWORD.
image: ubuntu:24.04
pipelines:
  default:
    - step:
        name: Build and sign
        script:
          - bash ./Sign-Code.sh --ci --pfx-base64-env SIGN_PFX_B64 --folder out
        artifacts: [ out/** ]
TPL_EOF
;;
    teamcity-build-step.txt)
cat <<'TPL_EOF'
TeamCity: add a build step "PowerShell" (Windows agent, PowerShell 7, script: file) or "Command Line" (Linux agent).
Parameters (type password): env.SIGN_PFX_B64 and env.SIGN_PFX_PASSWORD.
  Windows:  pwsh -File ./Sign-Code.ps1 -Ci -PfxBase64Env SIGN_PFX_B64 -Folder out
  Linux:    bash ./Sign-Code.sh --ci --pfx-base64-env SIGN_PFX_B64 --folder out
Warnings and errors appear as TeamCity build messages (##teamcity[message ...]).
TPL_EOF
;;
    aws-codebuild-buildspec.yml)
cat <<'TPL_EOF'
# AWS CodeBuild (Linux image with PowerShell, or a Windows image). Secrets from Secrets Manager / Parameter Store.
# Keys in AWS KMS: -Provider AwsKms (Jsign needs Java). The build role needs kms:Sign and kms:DescribeKey.
version: 0.2
env:
  secrets-manager:
    SIGN_PFX_B64: codesign/pfx:pfx_base64
    SIGN_PFX_PASSWORD: codesign/pfx:password
phases:
  build:
    commands:
      - dotnet build -c Release -o out
      - bash ./Sign-Code.sh --ci --pfx-base64-env SIGN_PFX_B64 --folder out
      # KMS example:
      # - bash ./Sign-Code.sh --ci --provider awskms --provider-arg "eu-central-1|alias/codesign" --cert-file codesign.cer --folder out
artifacts:
  files: [ 'out/**/*' ]
TPL_EOF
;;
    google-cloudbuild.yaml)
cat <<'TPL_EOF'
# Google Cloud Build. Secrets from Secret Manager. Keys in Cloud KMS: --provider gcpkms (Jsign needs Java).
steps:
  - name: 'mcr.microsoft.com/dotnet/sdk:9.0'
    entrypoint: bash
    args: ['-c', 'dotnet build -c Release -o out']
  - name: 'mcr.microsoft.com/dotnet/sdk:9.0'
    entrypoint: bash
    args: ['-c', './Sign-Code.sh --ci --pfx-base64-env SIGN_PFX_B64 --folder out']
    secretEnv: ['SIGN_PFX_B64', 'SIGN_PFX_PASSWORD']
availableSecrets:
  secretManager:
    - { versionName: projects/$PROJECT_ID/secrets/sign-pfx-b64/versions/latest, env: SIGN_PFX_B64 }
    - { versionName: projects/$PROJECT_ID/secrets/sign-pfx-password/versions/latest, env: SIGN_PFX_PASSWORD }
TPL_EOF
;;
    alibaba-yunxiao-flow.yml)
cat <<'TPL_EOF'
# Alibaba Cloud Yunxiao (Apsara DevOps) Flow - a GENERIC example: copy the two commands into a "Run shell" step
# of your pipeline (Linux build) or "Run PowerShell" step (Windows build). Keep the .pfx (base64) and its password
# in the Flow "Variables" marked secret, or fetch them from KMS Secrets Manager into the two environment variables.
# Alibaba KMS has no code-signing API: use the .pfx secret (private PKI) or a PKCS#11 HSM (-Provider Pkcs11).
stages:
  - name: sign
    steps:
      - run: |
          export SIGN_PFX_B64="$SIGN_PFX_B64" SIGN_PFX_PASSWORD="$SIGN_PFX_PASSWORD"
          bash ./Sign-Code.sh --ci --pfx-base64-env SIGN_PFX_B64 --folder ./out
TPL_EOF
;;
    Sign-Code.targets)
cat <<'TPL_EOF'
<Project>
  <!--
    Visual Studio 2026 / MSBuild: sign the build output after the build.
    1. Put Sign-Code.ps1 in the repository (for example in /build) and import this file in Directory.Build.targets:
         <Import Project="build\Sign-Code.targets" />
    2. Developer PC: nothing happens (SignCode is false). Build agent: dotnet build -p:SignCode=true
       with the secret variables SIGN_PFX_B64 and SIGN_PFX_PASSWORD set.
    3. -p:SignTimestamp=GlobalSign changes the timestamp server.
    4. Local build with the certificate of GenerateCodeSigningCertificate.ps1 (Visual Studio "Build" works too):
         dotnet build -p:SignCode=true -p:SignCodeArgs="-UseGenerated"
       or with a certificate in your Windows store:  -p:SignCodeArgs="-Subject 'CN=Agantra Inovatif OU'"
       Warnings and errors show in the Visual Studio Error List.
  -->
  <PropertyGroup>
    <SignCode Condition="'$(SignCode)' == ''">false</SignCode>
    <SignTimestamp Condition="'$(SignTimestamp)' == ''">DigiCert</SignTimestamp>
    <SignCodeScript Condition="'$(SignCodeScript)' == ''">$(MSBuildThisFileDirectory)Sign-Code.ps1</SignCodeScript>
    <SignCodeArgs Condition="'$(SignCodeArgs)' == ''">-Ci -PfxBase64Env SIGN_PFX_B64</SignCodeArgs>
  </PropertyGroup>
  <Target Name="SignCodeAfterBuild" AfterTargets="CopyFilesToOutputDirectory" Condition="'$(SignCode)' == 'true'">
    <Exec Command="pwsh -NoProfile -File &quot;$(SignCodeScript)&quot; $(SignCodeArgs) -Timestamp $(SignTimestamp) -File &quot;@(IntermediateAssembly->'%(FullPath)')&quot;" />
  </Target>
</Project>
TPL_EOF
;;
  esac
}

# ---------------------------------------------------------------- helpers
# where we run: azure = Azure DevOps Services (dev.azure.com, cloud), azure-server = Azure DevOps Server (on premises)
CI=0; ENVKIND=local
if [ "${GITHUB_ACTIONS:-}" = true ]; then ENVKIND=github
elif [ "${TF_BUILD:-}" = True ]; then case "${SYSTEM_COLLECTIONURI:-}" in *dev.azure.com*|*.visualstudio.com*) ENVKIND=azure;; *) ENVKIND=azure-server;; esac
elif [ "${GITLAB_CI:-}" = true ]; then ENVKIND=gitlab
elif [ -n "${JENKINS_URL:-}" ]; then ENVKIND=jenkins
elif [ -n "${TEAMCITY_VERSION:-}" ]; then ENVKIND=teamcity
elif [ -n "${BITBUCKET_BUILD_NUMBER:-}" ]; then ENVKIND=bitbucket
elif [ -n "${CODEBUILD_BUILD_ID:-}" ]; then ENVKIND=aws
elif [ -n "${CLOUD_BUILD_ID:-}" ]; then ENVKIND=gcp
elif [ -n "${MSBUILDEXTENSIONSPATH:-}${MSBuildExtensionsPath:-}" ]; then ENVKIND=msbuild; fi
case "$ENVKIND" in
  github) ENVLABEL='GitHub Actions';; azure) ENVLABEL='Azure DevOps Services (cloud)';; azure-server) ENVLABEL='Azure DevOps Server (on premises)';;
  gitlab) ENVLABEL='GitLab CI/CD';; jenkins) ENVLABEL=Jenkins;; teamcity) ENVLABEL=TeamCity;; bitbucket) ENVLABEL='Bitbucket Pipelines';;
  aws) ENVLABEL='AWS CodeBuild';; gcp) ENVLABEL='Google Cloud Build';; msbuild) ENVLABEL='MSBuild (dotnet build)';; *) ENVLABEL='manual run';;
esac
# a pipeline is a pipeline even without --ci: no questions there
case "$ENVKIND" in local|msbuild) ;; *) CI=1;; esac
VERBOSE=0; SECRETS=()
TMPFILES=(); CLEANUPS=()
mask() { local t="$*" x; for x in "${SECRETS[@]:-}"; do [ ${#x} -ge 3 ] && t="${t//"$x"/***}"; done; printf '%s' "$t"; }
add_secret() { [ -n "$1" ] || return 0; SECRETS+=("$1"); [ "$ENVKIND" = github ] && echo "::add-mask::$1"; return 0; }
say() {
  local l="$1"; shift
  local t; t=$(mask "$*")
  printf '[%s] %s\n' "$l" "$t"
  if [ $CI = 1 ]; then
    case "$ENVKIND:$l" in
      github:ERROR) printf '::error::%s\n' "$t";; github:WARN) printf '::warning::%s\n' "$t";;
      azure*:ERROR) printf '##vso[task.logissue type=error]%s\n' "$t";; azure*:WARN) printf '##vso[task.logissue type=warning]%s\n' "$t";;
      teamcity:ERROR|teamcity:WARN) local e; e=$(printf '%s' "$t" | sed "s/[|']/|&/g; s/\[/|[/g; s/\]/|]/g"); printf "##teamcity[message text='%s' status='%s']\n" "$e" "$([ "$l" = ERROR ] && echo ERROR || echo WARNING)";;
      msbuild:ERROR) printf 'Sign-Code : error SC0001: %s\n' "$t";; msbuild:WARN) printf 'Sign-Code : warning SC0001: %s\n' "$t";;
    esac
  fi
}
# --verbose: every step and every command line (passwords shown as ***) and the output of the tools
vsay() { [ $VERBOSE = 1 ] && printf '[VERBOSE] %s\n' "$(mask "$*")" >&2; return 0; }
vcmd() { [ $VERBOSE = 1 ] || return 0; local a q=""; for a in "$@"; do case "$a" in *[[:space:]]*) q="$q \"$a\"";; *) q="$q $a";; esac; done; printf '[VERBOSE] >%s\n' "$(mask "$q")" >&2; }
vout() { [ $VERBOSE = 1 ] && [ -n "$1" ] && printf '%s\n' "$1" | while IFS= read -r l; do printf '[VERBOSE]   %s\n' "$(mask "$l")" >&2; done; return 0; }
fail() { say ERROR "$2"; EXIT=$1; exit $1; }
# temporary files live in one private folder of this run, removed at the end ($(tmpfile) runs in a sub-shell, so a list would be lost)
SIGN_TMPDIR=$(mktemp -d "${TMPDIR:-/tmp}/signcode.XXXXXX"); chmod 700 "$SIGN_TMPDIR"
tmpfile() { local f; f=$(mktemp "$SIGN_TMPDIR/t.XXXXXX$1"); chmod 600 "$f"; printf '%s' "$f"; }
cleanup() { [ -n "${SIGN_TMPDIR:-}" ] && [ -d "$SIGN_TMPDIR" ] && rm -rf -- "$SIGN_TMPDIR"; }
trap cleanup EXIT
lc() { printf '%s' "$1" | tr 'A-Z' 'a-z'; }
get_secret() {  # env-name prompt  -> value on stdout (may be empty)
  local v="${!1:-}"; if [ -n "$v" ]; then printf '%s' "$v"; return; fi
  if [ $CI = 1 ] || [ ! -t 0 ]; then return; fi
  read -r -s -p "$2: " v; echo >&2; printf '%s' "$v"
}
hexhash() { # alg file
  case "$1" in
    sha256) if command -v sha256sum >/dev/null; then sha256sum "$2" | cut -d' ' -f1; else shasum -a 256 "$2" | cut -d' ' -f1; fi;;
    sha512) if command -v sha512sum >/dev/null; then sha512sum "$2" | cut -d' ' -f1; else shasum -a 512 "$2" | cut -d' ' -f1; fi;;
  esac
}
SUDO=""; [ "$(id -u)" -ne 0 ] && command -v sudo >/dev/null && SUDO="sudo"

declare -A KIND
for e in exe dll sys ocx scr cpl efi msi cab cat msix appx; do KIND[$e]=authenticode; done
for e in ps1 psm1 psd1 ps1xml psc1 cdxml; do KIND[$e]=powershell; done
for e in jar war ear aab; do KIND[$e]=java; done
KIND[apk]=apk; KIND[nupkg]=nuget; KIND[snupkg]=nuget
# Apple (rcodesign): Mach-O files (also without an extension), bundles (folders .app .framework ...), disk images, installer packages
for e in dylib dmg pkg app framework appex xpc kext plugin bundle; do KIND[$e]=apple; done
APPLE_BUNDLES=" app framework appex xpc kext plugin bundle "
file_kind() {  # path -> kind (empty = not supported)
  local f="$1" ext="" b
  case "$(basename "$f")" in *.*) ext=$(lc "${f##*.}");; esac
  if [ -d "$f" ]; then case "$APPLE_BUNDLES" in *" $ext "*) echo apple;; esac; return; fi
  if [ -n "$ext" ]; then echo "${KIND[$ext]:-}"; return; fi
  b=$(head -c 4 "$f" 2>/dev/null | od -An -tx1 | tr -d ' \n')
  case "$b" in feedface|feedfacf|cefaedfe|cffaedfe|cafebabe|bebafeca) echo apple;; esac
}
# the platform of a kind: which generated certificate signs it (--use-generated)
kind_platform() { case "$1" in java) echo java;; apk) echo android;; apple) case "$2" in *.pkg|*.PKG) echo apple-installer;; *) echo apple;; esac;; *) echo windows;; esac; }
for e in docm xlsm pptm dotm xlam ppam xltm potm doc xls ppt dot xla vbs js wsf appxbundle msixbundle winmd xll ax drv; do KIND[$e]=windows-only; done
declare -A TSA=( [digicert]=http://timestamp.digicert.com [globalsign]=http://timestamp.globalsign.com/tsa/r6advanced1
  [certum]=http://time.certum.pl [sectigo]=http://timestamp.sectigo.com [sslcom]=http://ts.ssl.com [entrust]=http://timestamp.entrust.net/TSS/RFC3161sha2TS
  [microsoft]=http://timestamp.acs.microsoft.com [apple]=http://timestamp.apple.com/ts01 [identrust]=http://timestamp.identrust.com
  [quovadis]=http://ts.quovadisglobal.com/eu [swisssign]=http://tsa.swisssign.net [buypass]=http://timestamp.buypass.no/RFC3161
  [harica]=http://ts.harica.gr [freetsa]=https://freetsa.org/tsr )
# --timestamp-fallback: when the chosen server fails its check, these are tried in this order
TSA_FALLBACK=(digicert sectigo globalsign sslcom certum entrust microsoft)

# ---------------------------------------------------------------- templates
write_templates() {
  local which="$1" dir="$SCRIPT_DIR/transport/signing-ci_$(date +%Y%m%d-%H%M%S)" n
  mkdir -p "$dir"
  local -a all=(github-actions.yml azure-pipelines.yml azure-devops-server-pipelines.yml gitlab-ci.yml Jenkinsfile bitbucket-pipelines.yml teamcity-build-step.txt aws-codebuild-buildspec.yml google-cloudbuild.yaml alibaba-yunxiao-flow.yml Sign-Code.targets)
  local -a sel
  case "$which" in all) sel=("${all[@]}");; github) sel=(github-actions.yml);; azure) sel=(azure-pipelines.yml);; azure-server) sel=(azure-devops-server-pipelines.yml);;
    gitlab) sel=(gitlab-ci.yml);; jenkins) sel=(Jenkinsfile);; bitbucket) sel=(bitbucket-pipelines.yml);; teamcity) sel=(teamcity-build-step.txt);;
    aws) sel=(aws-codebuild-buildspec.yml);; gcp) sel=(google-cloudbuild.yaml);; alibaba) sel=(alibaba-yunxiao-flow.yml);; msbuild) sel=(Sign-Code.targets);;
    *) die 1 "--template '$which' is not github, azure, azure-server, gitlab, jenkins, bitbucket, teamcity, aws, gcp, alibaba, msbuild or all.";; esac
  for n in "${sel[@]}"; do template_text "$n" > "$dir/$n"; say OK "Written: $dir/$n"; done
  say INFO 'These are starting points. Edit the names, paths and secret names. They were not run on a real pipeline.'
}
die() { say ERROR "$2"; exit "$1"; }

# ---------------------------------------------------------------- platform and tools
OSID=unknown; PKGMGR=""
check_platform() {
  if [ -n "${PKI_FAKE_OS:-}" ]; then say WARN 'PKI_FAKE_OS is set: platform check skipped (test only).'; else
    [ "$(uname -s)" = Linux ] || die 5 'Sign-Code.sh runs on Linux (Ubuntu 24+, CentOS Stream 10, RHEL 10, Rocky 10, Oracle Linux 10). On Windows use Sign-Code.ps1.'
  fi
  local id="" ver="" like=""
  if [ -r /etc/os-release ]; then id=$(. /etc/os-release; echo "${ID:-}"); ver=$(. /etc/os-release; echo "${VERSION_ID:-}"); like=$(. /etc/os-release; echo "${ID_LIKE:-}"); fi
  OSID="$id"; local major=${ver%%.*}
  case "$id" in
    ubuntu) PKGMGR=apt; [ "${major:-0}" -ge 24 ] 2>/dev/null || say WARN "Ubuntu $ver: version 24.04 or newer is supported.";;
    centos|rhel|rocky|ol|almalinux) PKGMGR=dnf; [ "${major:-0}" -ge 10 ] 2>/dev/null || say WARN "$id $ver: version 10 or newer is supported.";;
    debian) PKGMGR=apt; say WARN 'Debian is not in the supported list; the Ubuntu steps are used.';;
    *) case " $like " in *" rhel "*|*" fedora "*) PKGMGR=dnf;; *" debian "*|*" ubuntu "*) PKGMGR=apt;; esac
       [ -n "$PKGMGR" ] && say WARN "Linux '$id' is not in the supported list; using $PKGMGR." || { [ -n "${PKI_FAKE_OS:-}" ] || die 5 "Linux '$id' is not supported (Ubuntu 24+, CentOS Stream 10, RHEL 10, Rocky 10, Oracle Linux 10)."; };;
  esac
  say INFO "Linux $id $ver ($PKGMGR): supported."
}
JSIGN_JAR_DIR="${XDG_DATA_HOME:-$HOME/.local/share}/signcode"
find_tool() {
  case "$1" in
    osslsigncode|jarsigner|keytool|dotnet|smctl|curl|openssl|az|gcloud) command -v "$1";;
    rcodesign) command -v rcodesign || { [ -x "$HOME/.cargo/bin/rcodesign" ] && echo "$HOME/.cargo/bin/rcodesign"; };;
    apksigner) command -v apksigner || { local h f; for h in "${ANDROID_HOME:-}" "${ANDROID_SDK_ROOT:-}" "$HOME/Android/Sdk" /opt/android-sdk; do [ -n "$h" ] && f=$(ls -1 "$h"/build-tools/*/apksigner 2>/dev/null | sort | tail -1) && [ -n "$f" ] && { echo "$f"; return; }; done; };;
    jsign) command -v jsign || { [ -f "$JSIGN_JAR_DIR/jsign.sh" ] && echo "$JSIGN_JAR_DIR/jsign.sh"; };;
  esac
}
pkg_install() {  # packages...
  [ "$INSTALLER" = none ] && return 1
  if [ "$PKGMGR" = apt ]; then $SUDO env DEBIAN_FRONTEND=noninteractive apt-get install -y "$@" >&2
  else $SUDO dnf install -y "$@" >&2; fi
}
apt_update_once() { [ -n "${APT_UPDATED:-}" ] || { [ "$PKGMGR" = apt ] && $SUDO apt-get update -y >&2; APT_UPDATED=1; }; }
enable_epel() {
  case "$OSID" in
    ol) $SUDO dnf install -y oracle-epel-release-el10 >&2;;
    rhel) $SUDO dnf install -y "https://dl.fedoraproject.org/pub/epel/epel-release-latest-10.noarch.rpm" >&2;;
    *) $SUDO dnf config-manager --set-enabled crb >&2 2>/dev/null || true; $SUDO dnf install -y epel-release >&2;;
  esac
}
add_extra_repo() {
  if [ "$PKGMGR" = apt ] && [ -n "$PPA" ]; then $SUDO apt-get install -y software-properties-common >&2; $SUDO add-apt-repository -y "$PPA" >&2; APT_UPDATED=""; apt_update_once; fi
  if [ "$PKGMGR" = dnf ] && [ -n "$COPR" ]; then $SUDO dnf install -y dnf-plugins-core >&2; $SUDO dnf copr enable -y "$COPR" >&2; fi
}
install_jsign() {
  find_tool java >/dev/null 2>&1 || command -v java >/dev/null || install_tool jarsigner
  command -v curl >/dev/null || { apt_update_once; pkg_install curl ca-certificates; }
  mkdir -p "$JSIGN_JAR_DIR"
  local ver jar
  ver=$(curl -fsSL https://repo1.maven.org/maven2/net/jsign/jsign/maven-metadata.xml | sed -n 's/.*<release>\(.*\)<\/release>.*/\1/p') || true
  [ -n "$ver" ] || die 4 'Could not read the Jsign version from Maven Central (network?). Install Jsign by hand (https://ebourg.github.io/jsign/) and run again.'
  jar="$JSIGN_JAR_DIR/jsign-$ver.jar"
  curl -fsSL -o "$jar" "https://repo1.maven.org/maven2/net/jsign/jsign/$ver/jsign-$ver.jar" || die 4 'Jsign download failed.'
  local want got; want=$(curl -fsSL "https://repo1.maven.org/maven2/net/jsign/jsign/$ver/jsign-$ver.jar.sha1") || true
  got=$(sha1sum "$jar" | cut -d' ' -f1)
  [ -n "$want" ] && [ "${want%% *}" = "$got" ] || { rm -f "$jar"; die 4 'The Jsign download does not match the SHA-1 published on Maven Central. Not used.'; }
  printf '#!/bin/sh\nexec java -jar "%s" "$@"\n' "$jar" > "$JSIGN_JAR_DIR/jsign.sh"; chmod +x "$JSIGN_JAR_DIR/jsign.sh"
}
install_tool() {
  local t="$1"
  say WARN "$t was not found."
  [ "$INSTALLER" = none ] && die 4 "$t is missing and --installer none was given. Install it and run again."
  [ -n "$PKGMGR" ] || die 4 "No package manager known: install $t by hand."
  add_extra_repo
  apt_update_once
  case "$t" in
    osslsigncode) [ "$PKGMGR" = dnf ] && enable_epel; pkg_install osslsigncode || die 4 'osslsigncode could not be installed.';;
    jarsigner|keytool) if [ "$PKGMGR" = apt ]; then pkg_install default-jdk-headless; else pkg_install java-21-openjdk-devel || pkg_install java-17-openjdk-devel; fi || die 4 'The JDK could not be installed.';;
    apksigner) if [ "$PKGMGR" = apt ]; then pkg_install apksigner || die 4 'apksigner could not be installed.'; else
         die 4 "apksigner has no RPM package. Install the Android command-line tools, run  sdkmanager 'build-tools;35.0.0'  and set ANDROID_HOME (or use --copr owner/project with an apksigner package)."; fi;;
    dotnet) if [ "$PKGMGR" = apt ]; then pkg_install dotnet-sdk-9.0 || pkg_install dotnet-sdk-8.0 || { $SUDO apt-get install -y software-properties-common >&2; $SUDO add-apt-repository -y ppa:dotnet/backports >&2; APT_UPDATED=""; apt_update_once; pkg_install dotnet-sdk-9.0 || pkg_install dotnet-sdk-8.0; }
            else pkg_install dotnet-sdk-9.0 || pkg_install dotnet-sdk-8.0; fi || die 4 'The .NET SDK could not be installed.';;
    jsign) install_jsign;;
    curl|openssl) pkg_install "$t" ca-certificates || die 4 "$t could not be installed.";;
    rcodesign) command -v cargo >/dev/null || die 4 'rcodesign is missing. Install Rust (https://rustup.rs) and run again, or download rcodesign from https://github.com/indygreg/apple-platform-rs/releases and put it on PATH.'
       say INFO 'cargo install --locked apple-codesign'; cargo install --locked apple-codesign >&2 || die 4 'rcodesign could not be installed.';;
    smctl) die 4 'smctl (DigiCert KeyLocker client tools) must be installed by you: https://docs.digicert.com/ . Add it to PATH and run again.';;
    az|gcloud) die 4 "$t (the cloud CLI) must be installed by you and logged in.";;
  esac
  hash -r
  [ -n "$(find_tool "$t")" ] || die 4 "$t was installed but is still not found."
  say OK "$t is ready."
}
need_tool() { local p; p=$(find_tool "$1"); if [ -z "$p" ]; then install_tool "$1"; p=$(find_tool "$1"); fi; printf '%s' "$p"; }

# ---------------------------------------------------------------- certificate checks (openssl)
oidname() { case "$1" in 1.3.6.1.5.5.7.3.3) echo 'Code Signing';; *) echo "$1";; esac; }
CERT_ERR=(); CERT_WARN=()
check_certificate() {   # pem-file source chain
  local pem="$1" source="$2" chain="$3" t
  CERT_ERR=(); CERT_WARN=()
  t=$("$OSSL" x509 -in "$pem" -noout -text -nameopt RFC2253 2>/dev/null) || { CERT_ERR+=("OpenSSL cannot read the certificate."); return; }
  CERT_TEXT="$t"
  "$OSSL" x509 -in "$pem" -noout -checkend 0 >/dev/null || CERT_ERR+=("The certificate has EXPIRED ($("$OSSL" x509 -in "$pem" -noout -enddate | cut -d= -f2)).")
  if ! "$OSSL" x509 -in "$pem" -noout -checkend -0 >/dev/null 2>&1; then :; fi
  local nb now_ok; nb=$("$OSSL" x509 -in "$pem" -noout -startdate | cut -d= -f2)
  [ "$(date -d "$nb" +%s 2>/dev/null || echo 0)" -le "$(date +%s)" ] || CERT_ERR+=("The certificate is not valid yet (starts $nb).")
  "$OSSL" x509 -in "$pem" -noout -checkend $((30*86400)) >/dev/null || { "$OSSL" x509 -in "$pem" -noout -checkend 0 >/dev/null && CERT_WARN+=("The certificate expires in less than 30 days. Signatures with a timestamp stay valid after that."); }
  # purposes
  if ! printf '%s' "$t" | grep -q 'X509v3 Extended Key Usage'; then CERT_ERR+=('The certificate has no Extended Key Usage. A code-signing certificate must have "Code Signing" (1.3.6.1.5.5.7.3.3).')
  else
    local eku; eku=$(printf '%s\n' "$t" | sed -n '/X509v3 Extended Key Usage/{n;p}' | sed 's/^ *//')
    printf '%s' "$eku" | grep -q 'Code Signing' || CERT_ERR+=("The certificate is not for Code Signing. Its purposes: $eku.")
    printf '%s' "$eku" | grep -qE 'TLS Web|E-mail Protection|Time Stamping|Any Extended' && CERT_WARN+=("The certificate also has other purposes ($eku). Public CAs forbid this for code signing; use a dedicated certificate.")
  fi
  if printf '%s' "$t" | grep -q 'X509v3 Key Usage'; then
    printf '%s\n' "$t" | sed -n '/X509v3 Key Usage/{n;p}' | grep -q 'Digital Signature' || CERT_ERR+=('Key Usage does not include Digital Signature.')
  else CERT_WARN+=('The certificate has no Key Usage extension (it should say Digital Signature).'); fi
  printf '%s' "$t" | grep -q 'CA:TRUE' && CERT_ERR+=('This is a CA certificate (CA:TRUE). A CA must never sign code. Use a leaf certificate.')
  # key
  local alg bits; alg=$(printf '%s\n' "$t" | sed -n 's/^ *Public Key Algorithm: *//p' | head -1)
  CERT_KEYTEXT="$alg"
  if printf '%s' "$alg" | grep -qi 'rsaEncryption\|^rsa'; then
    bits=$(printf '%s\n' "$t" | sed -n 's/^ *Public-Key: *(\([0-9]*\) bit).*/\1/p' | head -1); CERT_KEYTEXT="RSA-$bits"
    if [ "$bits" -lt 2048 ]; then CERT_ERR+=("RSA-$bits is too weak. At least RSA-2048 (public CAs: RSA-3072).")
    elif [ "$bits" -lt 3072 ] && [ "$source" = publicca ]; then CERT_ERR+=("A public code-signing certificate must have RSA-3072 or larger (CA/Browser Forum). This one is RSA-$bits.")
    elif [ "$bits" -lt 3072 ]; then CERT_WARN+=("RSA-$bits works, but RSA-3072 or ECDSA P-384 is recommended."); fi
    [ "$bits" -gt 4096 ] && CERT_WARN+=("RSA-$bits is larger than 4096: some signing tools and Windows components refuse it.")
  elif printf '%s' "$alg" | grep -qi 'ec'; then
    bits=$(printf '%s\n' "$t" | sed -n 's/^ *Public-Key: *(\([0-9]*\) bit).*/\1/p' | head -1); CERT_KEYTEXT="ECDSA-$bits"
    [ "$bits" -lt 256 ] && CERT_ERR+=("ECDSA key size $bits is too small (P-256 or larger).")
    [ "$bits" -gt 384 ] && CERT_WARN+=('ECDSA P-521 is not accepted by every signing tool. P-256 or P-384 is safest.')
  elif printf '%s' "$alg" | grep -qiE 'ml-dsa|mldsa|slh-dsa'; then CERT_ERR+=('An ML-DSA (quantum) certificate cannot sign code yet: Authenticode, jarsigner, apksigner and NuGet do not support it. Use an RSA or ECDSA code-signing leaf.')
  else CERT_ERR+=("Key type $alg is not supported for code signing."); fi
  printf '%s\n' "$t" | sed -n 's/^ *Signature Algorithm: *//p' | head -1 | grep -qiE 'md5|sha1' && CERT_ERR+=("The certificate is signed with a weak algorithm.")
  local subj iss; subj=$(printf '%s\n' "$t" | sed -n 's/^ *Subject: *//p' | head -1); iss=$(printf '%s\n' "$t" | sed -n 's/^ *Issuer: *//p' | head -1)
  [ "$subj" = "$iss" ] && CERT_WARN+=('The certificate is self-signed. Every computer that checks the signature must trust it by hand.')
  # chain
  CERT_CHAIN_OK=0
  # the code signing purpose is "codesign" in OpenSSL 3.4+; older versions have none (then only the chain is checked)
  local vargs=()
  "$OSSL" verify -purpose codesign /dev/null 2>&1 | grep -qi 'invalid purpose' || vargs=(-purpose codesign)
  # trusted: the --chain-file and the trust store of this computer (ca-certificates, or --trust-store)
  local ca=""
  if [ -n "$chain" ] && [ -f "$chain" ]; then ca="$chain"; vargs+=(-untrusted "$chain"); else [ -n "$CHAIN_UNTRUSTED" ] && vargs+=(-untrusted "$CHAIN_UNTRUSTED"); fi
  if [ -n "$TRUST_STORE" ]; then if [ -n "$ca" ]; then local both; both=$(tmpfile .pem); cat "$ca" "$TRUST_STORE" > "$both"; ca="$both"; else ca="$TRUST_STORE"; fi; fi
  [ -n "$ca" ] && vargs+=(-no-CApath -no-CAfile -CAfile "$ca")
  vcmd openssl verify "${vargs[@]}" "$pem"
  CERT_VERIFY=$("$OSSL" verify "${vargs[@]}" "$pem" 2>&1) && CERT_CHAIN_OK=1
  CERT_POLICY=""; printf '%s' "$t" | grep -q '2\.23\.140\.1\.3\b' && CERT_POLICY=EV
  [ -z "$CERT_POLICY" ] && printf '%s' "$t" | grep -q '2\.23\.140\.1\.4\.1\b' && CERT_POLICY=CSBR
}
show_certificate() {
  local pem="$1"
  echo; echo '----- CERTIFICATE USED FOR SIGNING ------------------------------------------------------'
  "$OSSL" x509 -in "$pem" -noout -subject -issuer -serial -dates -nameopt RFC2253 | sed 's/^/  /'
  echo "  Public key   : ${CERT_KEYTEXT:-?}"
  echo "  SHA-1        : $("$OSSL" x509 -in "$pem" -noout -fingerprint -sha1 | cut -d= -f2)"
  echo "  SHA-256      : $("$OSSL" x509 -in "$pem" -noout -fingerprint -sha256 | cut -d= -f2)"
  "$OSSL" x509 -in "$pem" -noout -ext extendedKeyUsage,keyUsage 2>/dev/null | sed 's/^/  /'
  echo '-----------------------------------------------------------------------------------------'
}

# ---------------------------------------------------------------- timestamp check
check_timestamp() {
  local url="$1" q r tok certs tsa nd
  q=$(tmpfile .tsq); r=$(tmpfile .tsr); tok=$(tmpfile .der); certs=$(tmpfile .pem)
  "$OSSL" ts -query -digest "$(printf 'signcode-check-%s' "$RANDOM$RANDOM$$" | sha256sum | cut -d' ' -f1)" -sha256 -cert -out "$q" 2>/dev/null || die 3 'OpenSSL could not build a timestamp request.'
  local codef errf code err; codef=$(tmpfile .code); errf=$(tmpfile .err)
  vsay "timestamp check: POST an RFC 3161 query to $url"
  curl -sS --max-time 20 -H 'Content-Type: application/timestamp-query' --data-binary "@$q" -o "$r" -w '%{http_code}' "$url" > "$codef" 2>"$errf" || true
  code=$(cat "$codef" 2>/dev/null); err=$(cat "$errf" 2>/dev/null)
  case "$code" in 200) ;; ''|000) die 3 "The timestamp server $url cannot be reached from this computer: ${err:-no answer}. Check the network / proxy / firewall, or choose another with --timestamp.";; *) die 3 "The timestamp server $url answered HTTP $code. Choose another with --timestamp or --timestamp-url.";; esac
  local txt; txt=$("$OSSL" ts -reply -in "$r" -text 2>&1) || die 3 "The answer of $url is not a valid RFC 3161 timestamp."
  printf '%s' "$txt" | grep -qE 'Status: (Granted|Granted with modifications)' || die 3 "The timestamp server $url refused the request: $(printf '%s' "$txt" | sed -n 's/^Status: *//p' | head -1)"
  "$OSSL" ts -reply -in "$r" -token_out -out "$tok" 2>/dev/null
  "$OSSL" pkcs7 -inform DER -in "$tok" -print_certs -out "$certs" 2>/dev/null
  [ -s "$certs" ] || { say WARN "The timestamp answer has no certificate inside; its validity cannot be checked."; say OK "Timestamp server answers: $url"; return; }
  tsa=$(awk '/BEGIN CERTIFICATE/{n++} n==1{print} /END CERTIFICATE/{if(n==1) exit}' "$certs")
  # the TSA certificate is the one with the timeStamping purpose
  local one i=0 found=""
  while true; do
    i=$((i+1)); one=$(awk -v k=$i '/BEGIN CERTIFICATE/{n++} n==k{print} /END CERTIFICATE/{if(n==k) exit}' "$certs"); [ -n "$one" ] || break
    if printf '%s\n' "$one" | "$OSSL" x509 -noout -ext extendedKeyUsage 2>/dev/null | grep -q 'Time Stamping'; then found="$one"; break; fi
  done
  [ -n "$found" ] && tsa="$found"
  printf '%s\n' "$tsa" | "$OSSL" x509 -noout -checkend 0 >/dev/null || die 3 "The certificate of the timestamp server has expired. Choose another server."
  nd=$(printf '%s\n' "$tsa" | "$OSSL" x509 -noout -enddate | cut -d= -f2)
  local left=$(( ( $(date -d "$nd" +%s) - $(date +%s) ) / 86400 ))
  say OK "Timestamp server answers: $url"
  say OK "Timestamp certificate: $(printf '%s\n' "$tsa" | "$OSSL" x509 -noout -subject -nameopt RFC2253 | sed 's/^subject=//')  valid until $nd ($left days left)"
  [ $left -lt 30 ] && say WARN "The timestamp certificate expires in $left days."
  return 0
}

# ---------------------------------------------------------------- files
FILES=(); SKIPPED=()
add_file() {
  local f="$1" k
  k=$(file_kind "$f")
  if [ -z "$k" ]; then SKIPPED+=("$f (not a supported file type)"); return; fi
  if [ "$k" = windows-only ]; then SKIPPED+=("$f (needs Windows: use Sign-Code.ps1)"); return; fi
  local x; for x in "${FILES[@]:-}"; do [ "$x" = "$f" ] && return; done
  FILES+=("$f")
}
resolve_files() {
  local f d i name ok p
  for f in "${FILE_ARGS[@]:-}"; do [ -n "$f" ] || continue; f="${f%/}"; [ -e "$f" ] || die 1 "File not found: $f"; add_file "$(cd "$(dirname "$f")" && pwd)/$(basename "$f")"; done
  for d in "${FOLDER_ARGS[@]:-}"; do
    [ -n "$d" ] || continue; [ -d "$d" ] || die 1 "Folder not found: $d"
    d=$(cd "$d" && pwd)
    local find_args=("$d"); [ $NORECURSE = 1 ] && find_args+=(-maxdepth 1)
    # an Apple bundle (.app .framework ...) is signed as ONE item: find does not go into it
    local prune=(); for i in $APPLE_BUNDLES; do prune+=(-o -iname "*.$i"); done
    while IFS= read -r -d '' i; do
      name=$(basename "$i"); [ -n "$(file_kind "$i")" ] || continue
      if [ ${#INCLUDE[@]} -gt 0 ]; then ok=0; for p in "${INCLUDE[@]}"; do case "$name" in $p) ok=1;; esac; done; [ $ok = 1 ] || continue; fi
      ok=0; for p in "${EXCLUDE[@]:-}"; do [ -n "$p" ] && case "$name" in $p) ok=1;; esac; done; [ $ok = 1 ] && continue
      add_file "$i"
    done < <(find "${find_args[@]}" -mindepth 1 \( -type d \( -false "${prune[@]}" \) -print0 -prune \) -o -type f -print0 | sort -z)
  done
}
write_hashes() {  # file -> prints names
  local f="$1" dir name a h out names=""; dir=$(dirname "$f"); name=$(basename "$f")
  [ -d "$f" ] && { printf '%s' '(bundle: the signature is inside it)'; return; }
  for a in sha256 sha512; do h=$(hexhash $a "$f"); out="$dir/$name-signed.$a"; printf '%s  %s\n' "$h" "$name" > "$out"; names="$names $(basename "$out")"; done
  printf '%s' "${names# }"
}

# ---------------------------------------------------------------- main
FILE_ARGS=(); FOLDER_ARGS=(); INCLUDE=(); EXCLUDE=(); NORECURSE=0; CERT_SOURCE=auto; PROVIDER=local; PFX=""; PFX_PASS_ENV=SIGN_PFX_PASSWORD
PFX_B64_ENV=""; CERT_PEM=""; KEY_PEM=""; KEY_PASS_ENV=SIGN_KEY_PASSWORD; CHAIN_FILE=""; CERT_FILE=""; PROVIDER_ARG=""; TIMESTAMP=digicert; TS_URL=""
DIGEST=sha256; DESCRIPTION=""; DESC_URL=""; OUT_FOLDER=""; INSTALLER=auto; CHECK_ONLY=0; STRICT=0; TEMPLATE=""; SHOW_CERT=0; PPA=""; COPR=""; OPENSSL_ARG=""
CHAIN_UNTRUSTED=""; EXIT=0
TS_GIVEN=0; USE_GEN=0; GEN_ROOT=""; GEN_PLATFORM=auto; CERT_FOLDER=""; TRUST_STORE=""; TS_FALLBACK=0; PASS_ARGS=()
need() { [ $# -ge 2 ] || die 1 "Option $1 needs a value."; }
while [ $# -gt 0 ]; do
  # the options a --use-generated run passes on to its per-platform runs (not the files, not the certificate choice)
  case "$1" in
    --file|--folder|--include|--exclude|--generated-root|--generated-platform) ;;
    --no-recurse|--use-generated) ;;
    -h|--help|--skip-signed|--check-only|--ci|--strict|--show-certificate|--verbose|--timestamp-fallback) PASS_ARGS+=("$1");;
    *) PASS_ARGS+=("$1"); [ $# -ge 2 ] && PASS_ARGS+=("$2");;
  esac
  case "$1" in
    --use-generated) USE_GEN=1;;
    --generated-root) need "$@"; GEN_ROOT="$2"; shift;;
    --generated-platform) need "$@"; GEN_PLATFORM=$(lc "$2"); shift;;
    --cert-folder) need "$@"; CERT_FOLDER="$2"; shift;;
    --trust-store) need "$@"; TRUST_STORE="$2"; shift;;
    --timestamp-fallback) TS_FALLBACK=1;;
    --verbose|-v) VERBOSE=1;;
    -h|--help) show_help | help_pager; exit 0;;
    --file) need "$@"; FILE_ARGS+=("$2"); shift;;
    --folder) need "$@"; FOLDER_ARGS+=("$2"); shift;;
    --include) need "$@"; INCLUDE+=("$2"); shift;;
    --exclude) need "$@"; EXCLUDE+=("$2"); shift;;
    --no-recurse) NORECURSE=1;;
    --cert-source) need "$@"; CERT_SOURCE=$(lc "$2"); shift;;
    --provider) need "$@"; PROVIDER=$(lc "$2"); shift;;
    --pfx) need "$@"; PFX="$2"; shift;;
    --pfx-password-env) need "$@"; PFX_PASS_ENV="$2"; shift;;
    --pfx-base64-env) need "$@"; PFX_B64_ENV="$2"; shift;;
    --cert-pem) need "$@"; CERT_PEM="$2"; shift;;
    --key-pem) need "$@"; KEY_PEM="$2"; shift;;
    --key-password-env) need "$@"; KEY_PASS_ENV="$2"; shift;;
    --chain-file) need "$@"; CHAIN_FILE="$2"; shift;;
    --cert-file) need "$@"; CERT_FILE="$2"; shift;;
    --provider-arg) need "$@"; PROVIDER_ARG="$2"; shift;;
    --timestamp) need "$@"; TIMESTAMP=$(lc "$2"); TS_GIVEN=1; shift;;
    --timestamp-url) need "$@"; TS_URL="$2"; shift;;
    --digest) need "$@"; DIGEST=$(lc "$2"); shift;;
    --description) need "$@"; DESCRIPTION="$2"; shift;;
    --description-url) need "$@"; DESC_URL="$2"; shift;;
    --out-folder) need "$@"; OUT_FOLDER="$2"; shift;;
    --skip-signed) ;;
    --installer) need "$@"; INSTALLER=$(lc "$2"); shift;;
    --ppa) need "$@"; PPA="$2"; shift;;
    --copr) need "$@"; COPR="$2"; shift;;
    --check-only) CHECK_ONLY=1;;
    --ci) CI=1;;
    --strict) STRICT=1;;
    --template) need "$@"; TEMPLATE=$(lc "$2"); shift;;
    --show-certificate) SHOW_CERT=1;;
    --openssl) need "$@"; OPENSSL_ARG="$2"; shift;;
    *) die 1 "Unknown option: $1   (see --help)";;
  esac
  shift
done
case "$DIGEST" in sha256|sha384|sha512) ;; *) die 1 "--digest '$DIGEST' is not sha256, sha384 or sha512.";; esac
case "$INSTALLER" in auto|none) ;; *) die 1 "--installer '$INSTALLER' is not auto or none.";; esac
if [ -n "$TEMPLATE" ]; then write_templates "$TEMPLATE"; exit 0; fi

printf '%s\n' '============================================================' 'Author : Nicko Satria Utama' 'Company: Agantra Inovatif OÜ (NextMantra)' 'Email  : nicko@nextmantra.com' '============================================================' ''
say INFO "Sign-Code.sh version $VERSION  ($ENVLABEL$([ $CI = 1 ] && echo ', pipeline mode'))"
check_platform
OSSL="$OPENSSL_ARG"; [ -n "$OSSL" ] || OSSL=$(command -v openssl || true)
[ -n "$OSSL" ] || { install_tool openssl; OSSL=$(command -v openssl); }
command -v curl >/dev/null || install_tool curl

resolve_files
for s in "${SKIPPED[@]:-}"; do [ -n "$s" ] && say WARN "Skipped: $s"; done
[ $CHECK_ONLY = 1 ] || [ ${#FILES[@]} -gt 0 ] || die 7 'No file to sign. Give --file and / or --folder (supported types: see --help).'
say INFO "${#FILES[@]} file(s) to sign."
for f in "${FILES[@]:-}"; do [ -n "$f" ] && vsay "file: $f  ($(file_kind "$f"))"; done

# ---- --use-generated: one run of this script per platform, each with the newest generated certificate of that platform
if [ $USE_GEN = 1 ]; then
  [ -z "$PFX$PFX_B64_ENV$CERT_PEM$CERT_FOLDER" ] || die 1 '--use-generated chooses the certificate itself: leave out --pfx, --pfx-base64-env, --cert-pem and --cert-folder.'
  GEN_ROOT="${GEN_ROOT:-$SCRIPT_DIR/leafcerts/codesign}"; idxf="$GEN_ROOT/codesign-index.tsv"
  [ -f "$idxf" ] || die 1 "No generated code signing certificate in $GEN_ROOT (codesign-index.tsv). Make one: bash devkit/GenerateCodeSigningCertificate.sh --platform windows   (or give --generated-root)."
  [ -n "${!PFX_PASS_ENV:-}" ] || { export "$PFX_PASS_ENV=Abc12345!"; say WARN "$PFX_PASS_ENV is not set: the default password of GenerateCodeSigningCertificate (Abc12345!) is used."; }
  today=$(date -u +%Y-%m-%d)
  declare -A GROUP=(); order=()
  for f in "${FILES[@]:-}"; do
    [ -n "$f" ] || continue
    pl="$GEN_PLATFORM"; [ "$pl" = auto ] && pl=$(kind_platform "$(file_kind "$f")" "$f")
    [ -n "${GROUP[$pl]:-}" ] || order+=("$pl"); GROUP[$pl]+="$f"$'\n'
  done
  [ ${#order[@]} -gt 0 ] || { [ $CHECK_ONLY = 1 ] && { pl="$GEN_PLATFORM"; [ "$pl" = auto ] && pl=windows; order=("$pl"); GROUP[$pl]=""; }; }
  worst=0
  for pl in "${order[@]}"; do
    row=""; for want in "$pl" $([ "$pl" = apple-installer ] && echo apple); do
      row=$(awk -F'\t' -v p="$want" -v t="$today" '!/^#/ && $1==p && substr($3,1,10)>=t {r=$0} END {print r}' "$idxf")
      [ -n "$row" ] && { [ "$want" != "$pl" ] && say WARN 'No Apple installer certificate: the Apple application certificate signs the .pkg files (make one: --platform apple --apple-type installer).'; break; }
    done
    if [ -z "$row" ]; then say ERROR "No valid generated $pl code signing certificate in $GEN_ROOT. Make one: bash devkit/GenerateCodeSigningCertificate.sh --platform ${pl%-installer}"; worst=2; continue; fi
    IFS=$'\t' read -r _ lvl na _ gpfx gcrt _ <<<"$row"
    gchain="$GEN_ROOT/${gcrt%.crt}-chain.crt"
    say INFO "---- $pl : $(printf '%s' "${GROUP[$pl]}" | grep -c .) file(s) with $(basename "${gcrt%.crt}") ($lvl, until $na)"
    sub=("${PASS_ARGS[@]}" --pfx "$GEN_ROOT/$gpfx")
    [ -z "$CHAIN_FILE" ] && [ -f "$gchain" ] && sub+=(--chain-file "$gchain")
    while IFS= read -r f; do [ -n "$f" ] && sub+=(--file "$f"); done <<<"${GROUP[$pl]}"
    vcmd bash "$0" "${sub[@]}"
    rc=0; bash "$0" "${sub[@]}" || rc=$?
    [ $rc -gt $worst ] && worst=$rc
  done
  exit $worst
fi
if [ -n "$CERT_FOLDER" ]; then
  # a folder of GenerateCodeSigningCertificate / GenerateLeafCertificate: its newest .pfx, and <name>-chain.crt for the chain check
  [ -d "$CERT_FOLDER" ] || die 1 "Folder not found: $CERT_FOLDER"
  PFX=$(ls -1t "$CERT_FOLDER"/*.pfx "$CERT_FOLDER"/*.p12 2>/dev/null | head -1)
  [ -n "$PFX" ] || die 1 "No .pfx / .p12 in $CERT_FOLDER."
  say INFO "Certificate file: $PFX"
  [ -z "$CHAIN_FILE" ] && [ -f "${PFX%.*}-chain.crt" ] && { CHAIN_FILE="${PFX%.*}-chain.crt"; vsay "chain: $CHAIN_FILE"; }
  if [ -z "${!PFX_PASS_ENV:-}" ] && { [ $CI = 1 ] || [ ! -t 0 ]; }; then export "$PFX_PASS_ENV=Abc12345!"; say WARN "$PFX_PASS_ENV is not set: the lab default password Abc12345! is tried."; fi
fi
# the trust store of this computer (ca-certificates): a private root installed with update-ca-certificates / update-ca-trust is trusted here
SYS_BUNDLE=""; for b in /etc/ssl/certs/ca-certificates.crt /etc/pki/tls/certs/ca-bundle.crt /etc/ssl/ca-bundle.pem /etc/pki/ca-trust/extracted/pem/tls-ca-bundle.pem; do [ -f "$b" ] && { SYS_BUNDLE="$b"; break; }; done
case "$TRUST_STORE" in ''|system) TRUST_STORE="$SYS_BUNDLE";; *) [ -f "$TRUST_STORE" ] || die 1 "Trust store not found: $TRUST_STORE";; esac
vsay "trust store: ${TRUST_STORE:-none}"

# ---- certificate: make a PEM (public) and a normalized temporary PFX (alias "signcode") for the tools
PUBPEM=$(tmpfile .pem); WORKPFX=""; WORKPASS=""
if [ "$PROVIDER" = local ]; then
  n=0; for v in "$PFX" "$PFX_B64_ENV" "$CERT_PEM"; do [ -n "$v" ] && n=$((n+1)); done
  [ $n -eq 1 ] || die 1 'Give exactly ONE certificate source: --use-generated, --pfx, --pfx-base64-env, --cert-folder or --cert-pem/--key-pem (or use --provider).'
  WORKPASS=$(head -c 24 /dev/urandom | od -An -tx1 | tr -d ' \n'); add_secret "$WORKPASS"
  export SIGNCODE_WORKPASS="$WORKPASS"
  WORKPFX=$(tmpfile .pfx)
  if [ -n "$PFX" ] || [ -n "$PFX_B64_ENV" ]; then
    SRCPFX="$PFX"
    if [ -n "$PFX_B64_ENV" ]; then
      [ -n "${!PFX_B64_ENV:-}" ] || die 1 "The environment variable $PFX_B64_ENV is empty or not set. In a pipeline, map the secret to it."
      SRCPFX=$(tmpfile .pfx); printf '%s' "${!PFX_B64_ENV}" | tr -d ' \n\r' | base64 -d > "$SRCPFX" || die 1 "$PFX_B64_ENV is not valid base64."
    fi
    [ -f "$SRCPFX" ] || die 1 "PFX file not found: $SRCPFX"
    export SIGNCODE_SRCPASS; SIGNCODE_SRCPASS=$(get_secret "$PFX_PASS_ENV" 'PFX password')
    add_secret "$SIGNCODE_SRCPASS"
    ALLPEM=$(tmpfile .pem)
    "$OSSL" pkcs12 -in "$SRCPFX" -nodes -passin env:SIGNCODE_SRCPASS -out "$ALLPEM" 2>/dev/null || "$OSSL" pkcs12 -legacy -in "$SRCPFX" -nodes -passin env:SIGNCODE_SRCPASS -out "$ALLPEM" 2>/dev/null || die 1 "The PFX could not be opened (wrong password in $PFX_PASS_ENV?)."
    "$OSSL" pkcs12 -in "$SRCPFX" -nokeys -clcerts -passin env:SIGNCODE_SRCPASS -out "$PUBPEM" 2>/dev/null || "$OSSL" pkcs12 -legacy -in "$SRCPFX" -nokeys -clcerts -passin env:SIGNCODE_SRCPASS -out "$PUBPEM" 2>/dev/null
    KEYTMP=$(tmpfile .key); awk '/BEGIN (ENCRYPTED |EC |RSA )?PRIVATE KEY/{p=1} p{print} /END (ENCRYPTED |EC |RSA )?PRIVATE KEY/{p=0}' "$ALLPEM" > "$KEYTMP"
    CHAINTMP=$(tmpfile .pem); "$OSSL" pkcs12 -in "$SRCPFX" -nokeys -cacerts -passin env:SIGNCODE_SRCPASS -out "$CHAINTMP" 2>/dev/null || "$OSSL" pkcs12 -legacy -in "$SRCPFX" -nokeys -cacerts -passin env:SIGNCODE_SRCPASS -out "$CHAINTMP" 2>/dev/null || true
    CHAIN_UNTRUSTED="$CHAINTMP"
  else
    [ -n "$KEY_PEM" ] || die 1 '--cert-pem needs --key-pem as well.'
    [ -f "$CERT_PEM" ] && [ -f "$KEY_PEM" ] || die 1 'Certificate or key file not found.'
    export SIGNCODE_KEYPASS; SIGNCODE_KEYPASS=$(get_secret "$KEY_PASS_ENV" 'Private key password (empty = none)'); add_secret "$SIGNCODE_KEYPASS"
    awk '/BEGIN CERTIFICATE/{n++} n==1{print} /END CERTIFICATE/{if(n==1) exit}' "$CERT_PEM" > "$PUBPEM"
    KEYTMP=$(tmpfile .key)
    if [ -n "$SIGNCODE_KEYPASS" ]; then "$OSSL" pkey -in "$KEY_PEM" -passin env:SIGNCODE_KEYPASS -out "$KEYTMP" 2>/dev/null || die 1 "The private key could not be opened (wrong password in $KEY_PASS_ENV?)."
    else "$OSSL" pkey -in "$KEY_PEM" -passin pass: -out "$KEYTMP" 2>/dev/null || die 1 'The private key could not be opened (is it encrypted? set the password variable).'; fi
    CHAINTMP=$(tmpfile .pem); awk '/BEGIN CERTIFICATE/{n++} n>=2{print}' "$CERT_PEM" > "$CHAINTMP"; CHAIN_UNTRUSTED="$CHAINTMP"
  fi
  [ -s "$PUBPEM" ] || die 1 'No certificate was found in the PFX / PEM.'
  # the private key must belong to the certificate
  [ "$("$OSSL" x509 -in "$PUBPEM" -noout -pubkey | tr -d ' \n')" = "$("$OSSL" pkey -in "$KEYTMP" -pubout 2>/dev/null | tr -d ' \n')" ] || die 1 'The private key does NOT belong to the certificate.'
  cf=(); [ -s "${CHAINTMP:-}" ] && cf=(-certfile "$CHAINTMP")
  "$OSSL" pkcs12 -export -inkey "$KEYTMP" -in "$PUBPEM" "${cf[@]}" -name signcode -out "$WORKPFX" -passout env:SIGNCODE_WORKPASS 2>/dev/null || die 1 'Could not prepare the signing key store.'
  rm -f "$KEYTMP"
else
  [ -n "$CERT_FILE" ] || die 1 "--provider $PROVIDER needs --cert-file <the public certificate> so that the checks can run."
  [ -f "$CERT_FILE" ] || die 1 "Certificate file not found: $CERT_FILE"
  "$OSSL" x509 -in "$CERT_FILE" -out "$PUBPEM" 2>/dev/null || "$OSSL" x509 -inform DER -in "$CERT_FILE" -out "$PUBPEM" || die 1 'The certificate file could not be read.'
fi

# ---- classify and CHECK
SRC="$CERT_SOURCE"
case "$SRC" in auto|privatepki|publicca) ;; *) die 1 "--cert-source '$SRC' is not auto, privatepki or publicca.";; esac
if [ "$SRC" = auto ]; then
  check_certificate "$PUBPEM" privatepki ""
  if [ $CERT_CHAIN_OK = 1 ] && [ "$(printf '%s' "$CERT_TEXT" | sed -n 's/^ *Subject: *//p' | head -1)" != "$(printf '%s' "$CERT_TEXT" | sed -n 's/^ *Issuer: *//p' | head -1)" ]; then SRC=publicca; else SRC=privatepki; fi
fi
say INFO "Certificate source: $SRC"
check_certificate "$PUBPEM" "$SRC" "$CHAIN_FILE"
if [ "$SRC" = publicca ]; then
  [ $CERT_CHAIN_OK = 1 ] || CERT_ERR+=("The chain does not end at a root that this computer trusts ($(printf '%s' "$CERT_VERIFY" | tail -1)).")
  [ -n "$CERT_POLICY" ] || CERT_WARN+=('No CA/Browser Forum code-signing policy (2.23.140.1.4.1 or EV 2.23.140.1.3) found in the certificate.')
elif [ $CERT_CHAIN_OK = 0 ]; then CERT_WARN+=('The chain is not complete / not trusted here. Give --chain-file <ca-bundle.pem> to check it against your private root.'); fi
for w in "${CERT_WARN[@]:-}"; do [ -n "$w" ] && say WARN "$w"; done
if [ ${#CERT_ERR[@]} -gt 0 ]; then
  for e in "${CERT_ERR[@]}"; do say ERROR "$e"; done
  show_certificate "$PUBPEM"
  die 2 'The certificate does NOT comply with the code-signing rules. Nothing was signed.'
fi
say OK "Certificate complies: $CERT_KEYTEXT, $([ "$CERT_POLICY" = EV ] && echo 'EV code signing' || { [ "$CERT_POLICY" = CSBR ] && echo 'OV code signing (CA/B Forum)' || echo 'code signing'; }), chain $([ $CERT_CHAIN_OK = 1 ] && echo verified || echo 'not verified')."

# ---- timestamp
if [ -n "$TS_URL" ]; then TSURL="$TS_URL"
elif [ -n "${TSA[$TIMESTAMP]:-}" ]; then TSURL="${TSA[$TIMESTAMP]}"
elif [[ "$TIMESTAMP" =~ ^https?:// ]]; then TSURL="$TIMESTAMP"
else die 1 "Unknown timestamp name '$TIMESTAMP'. Use: ${!TSA[*]} or --timestamp-url <url>."; fi
if [ $TS_FALLBACK = 0 ]; then check_timestamp "$TSURL"
else
  # the chosen server first, then the others of the fallback list until one passes the check
  cands=("$TSURL"); for n in "${TSA_FALLBACK[@]}"; do [ "${TSA[$n]}" = "$TSURL" ] || cands+=("${TSA[$n]}"); done
  okts=""; for u in "${cands[@]}"; do if ( die() { say WARN "$2"; exit "$1"; }; check_timestamp "$u" ); then okts="$u"; break; else say WARN "Trying the next timestamp server."; fi; done
  [ -n "$okts" ] || die 3 "No timestamp server answered (tried: ${cands[*]})."
  TSURL="$okts"
fi
vsay "timestamp server: $TSURL"
if [ $CHECK_ONLY = 1 ]; then show_certificate "$PUBPEM"; say OK 'Checks finished (--check-only): nothing was signed.'; exit 0; fi

# ---- tools needed for THIS job
declare -A KINDS_USED; for f in "${FILES[@]}"; do KINDS_USED[$(file_kind "$f")]=1; done
TOOL_OSS=""; TOOL_JAR=""; TOOL_APK=""; TOOL_DOTNET=""; TOOL_JSIGN=""; TOOL_SMCTL=""; TOOL_RCS=""
if [ "$PROVIDER" = local ]; then
  { [ -n "${KINDS_USED[authenticode]:-}" ] || [ -n "${KINDS_USED[powershell]:-}" ]; } && TOOL_OSS=$(need_tool osslsigncode)
  [ -n "${KINDS_USED[java]:-}" ] && TOOL_JAR=$(need_tool jarsigner)
  [ -n "${KINDS_USED[apk]:-}" ] && { TOOL_APK=$(need_tool apksigner); command -v jarsigner >/dev/null || need_tool jarsigner >/dev/null; }
  [ -n "${KINDS_USED[nuget]:-}" ] && TOOL_DOTNET=$(need_tool dotnet)
  [ -n "${KINDS_USED[apple]:-}" ] && TOOL_RCS=$(need_tool rcodesign)
else
  case "$PROVIDER" in
    digicertkeylocker) TOOL_SMCTL=$(need_tool smctl);;
    azurekeyvault|azuretrustedsigning) TOOL_JSIGN=$(need_tool jsign); need_tool az >/dev/null;;
    gcpkms) TOOL_JSIGN=$(need_tool jsign); need_tool gcloud >/dev/null;;
    awskms|pkcs11) TOOL_JSIGN=$(need_tool jsign);;
    *) die 1 "--provider '$PROVIDER' is not azurekeyvault, azuretrustedsigning, awskms, gcpkms, pkcs11 or digicertkeylocker.";;
  esac
fi
[ -z "$OUT_FOLDER" ] || mkdir -p "$OUT_FOLDER"

# ---- sign
IFS='|' read -r PA1 PA2 PA3 <<<"$PROVIDER_ARG"
ds_up=$(printf '%s' "$DIGEST" | tr 'a-z' 'A-Z'); ds_dash="${ds_up/SHA/SHA-}"
OKN=0; SKN=${#SKIPPED[@]}; FAILN=0; REPORT=(); idx=0
for src in "${FILES[@]}"; do
  idx=$((idx+1)); tgt="$src"
  if [ -n "$OUT_FOLDER" ]; then tgt="$OUT_FOLDER/$(basename "$src")"; rm -rf -- "$tgt"; cp -Rf "$src" "$tgt"; fi
  kind=$(file_kind "$tgt"); echo "[$idx/${#FILES[@]}] $tgt  ($kind)"
  msg=""; out=""; rc=0
  if [ "$PROVIDER" = local ]; then
    case "$kind" in
      authenticode|powershell)
        tmpout=$(tmpfile .signed); rm -f "$tmpout"
        oargs=(sign -pkcs12 "$WORKPFX" -pass "$WORKPASS" -h "$DIGEST" -ts "$TSURL" -in "$tgt" -out "$tmpout")
        [ -n "$DESCRIPTION" ] && oargs+=(-n "$DESCRIPTION"); [ -n "$DESC_URL" ] && oargs+=(-i "$DESC_URL")
        # -pass puts the one-time password of the temporary key store on the command line: it is random and only opens the temporary file
        vcmd "$TOOL_OSS" "${oargs[@]}"
        out=$("$TOOL_OSS" "${oargs[@]}" 2>&1) || rc=$?; vout "$out"
        if [ $rc -eq 0 ]; then
          vcmd "$TOOL_OSS" verify -in "$tmpout"
          out=$("$TOOL_OSS" verify -in "$tmpout" 2>&1); vrc=$?; vout "$out"
          if printf '%s' "$out" | grep -q 'Signature verification: ok'; then :; elif [ "$SRC" = publicca ]; then rc=1; else msg='signature written; the root is not trusted by this machine (normal for a private PKI)'; fi
          [ $rc -eq 0 ] && cp -f "$tmpout" "$tgt"
        fi;;
      java)
        jargs=(-keystore "$WORKPFX" -storetype PKCS12 -storepass:env SIGNCODE_WORKPASS -digestalg "$ds_dash" -tsa "$TSURL" -tsadigestalg "$ds_dash")
        [ $VERBOSE = 1 ] && jargs+=(-verbose)
        vcmd "$TOOL_JAR" "${jargs[@]}" "$tgt" signcode
        out=$("$TOOL_JAR" "${jargs[@]}" "$tgt" signcode 2>&1) || rc=$?; vout "$out"
        [ $rc -eq 0 ] && { vcmd "$TOOL_JAR" -verify "$tgt"; out=$("$TOOL_JAR" -verify "$tgt" 2>&1) || rc=$?; vout "$out"; };;
      apk)
        aargs=(sign --ks "$WORKPFX" --ks-type PKCS12 --ks-pass env:SIGNCODE_WORKPASS); [ $VERBOSE = 1 ] && aargs+=(--verbose)
        vcmd "$TOOL_APK" "${aargs[@]}" "$tgt"
        out=$("$TOOL_APK" "${aargs[@]}" "$tgt" 2>&1) || rc=$?; vout "$out"
        [ $rc -eq 0 ] && { vcmd "$TOOL_APK" verify --print-certs "$tgt"; out=$("$TOOL_APK" verify --print-certs "$tgt" 2>&1) || rc=$?; vout "$out"; msg='APK signed without a timestamp (the Android format has none)'; };;
      nuget)
        nargs=(nuget sign "$tgt" --certificate-path "$WORKPFX" --certificate-password "$WORKPASS" --timestamper "$TSURL" --timestamp-hash-algorithm "$DIGEST" --hash-algorithm "$DIGEST" --overwrite)
        [ $VERBOSE = 1 ] && nargs+=(--verbosity detailed)
        vcmd "$TOOL_DOTNET" "${nargs[@]}"
        out=$("$TOOL_DOTNET" "${nargs[@]}" 2>&1) || rc=$?; vout "$out";;
      apple)
        # rcodesign: Mach-O, bundles (.app ...), .dmg and installer packages (.pkg). Apple's timestamp server unless --timestamp / --timestamp-url was given.
        pwf=$(tmpfile .txt); printf '%s' "$WORKPASS" > "$pwf"
        ats="$TSURL"; [ -z "$TS_URL" ] && [ "$TS_GIVEN" = 0 ] && ats="${TSA[apple]}"
        rargs=(sign --p12-file "$WORKPFX" --p12-password-file "$pwf" --timestamp-url "$ats")
        case "$tgt" in *.pkg|*.dmg|*.PKG|*.DMG) ;; *) rargs+=(--code-signature-flags runtime);; esac
        [ $VERBOSE = 1 ] && rargs+=(-v)
        vcmd "$TOOL_RCS" "${rargs[@]}" "$tgt"
        out=$("$TOOL_RCS" "${rargs[@]}" "$tgt" 2>&1) || rc=$?; vout "$out"
        if [ $rc -eq 0 ]; then case "$tgt" in *.pkg|*.PKG) ;; *) vcmd "$TOOL_RCS" verify "$tgt"; out=$("$TOOL_RCS" verify "$tgt" 2>&1) || rc=$?; vout "$out";; esac; fi
        msg='signed for macOS; Gatekeeper also needs Apple notarization (public Apple Developer ID certificate)';;
    esac
  else
    case "$kind" in authenticode|powershell) ;; *) say WARN "Skipped (kind $kind is not signed by --provider $PROVIDER): $tgt"; SKN=$((SKN+1)); REPORT+=("{\"file\":\"$tgt\",\"status\":\"skipped\"}"); continue;; esac
    case "$PROVIDER" in
      azurekeyvault) export JSIGN_STOREPASS; JSIGN_STOREPASS=$(az account get-access-token --resource https://vault.azure.net --query accessToken -o tsv)
        out=$("$TOOL_JSIGN" --storetype AZUREKEYVAULT --keystore "$PA1" --alias "$PA2" --storepass env:JSIGN_STOREPASS --alg "$DIGEST" --tsaurl "$TSURL" --tsmode RFC3161 "$tgt" 2>&1) || rc=$?;;
      azuretrustedsigning) export JSIGN_STOREPASS; JSIGN_STOREPASS=$(az account get-access-token --resource https://codesigning.azure.net --query accessToken -o tsv)
        out=$("$TOOL_JSIGN" --storetype TRUSTEDSIGNING --keystore "$PA1" --alias "$PA2" --storepass env:JSIGN_STOREPASS --alg "$DIGEST" --tsaurl http://timestamp.acs.microsoft.com --tsmode RFC3161 "$tgt" 2>&1) || rc=$?;;
      awskms) export JSIGN_STOREPASS="${AWS_ACCESS_KEY_ID:-}|${AWS_SECRET_ACCESS_KEY:-}${AWS_SESSION_TOKEN:+|$AWS_SESSION_TOKEN}"
        out=$("$TOOL_JSIGN" --storetype AWS --keystore "$PA1" --alias "$PA2" --storepass env:JSIGN_STOREPASS --certfile "$CERT_FILE" --alg "$DIGEST" --tsaurl "$TSURL" --tsmode RFC3161 "$tgt" 2>&1) || rc=$?;;
      gcpkms) export JSIGN_STOREPASS; JSIGN_STOREPASS=$(gcloud auth print-access-token)
        out=$("$TOOL_JSIGN" --storetype GOOGLECLOUD --keystore "$PA1" --alias "$PA2" --storepass env:JSIGN_STOREPASS --certfile "$CERT_FILE" --alg "$DIGEST" --tsaurl "$TSURL" --tsmode RFC3161 "$tgt" 2>&1) || rc=$?;;
      pkcs11) export JSIGN_STOREPASS="${SIGN_PKCS11_PIN:-}"
        out=$("$TOOL_JSIGN" --storetype PKCS11 --keystore "$PA1" --alias "$PA2" --storepass env:JSIGN_STOREPASS --certfile "$CERT_FILE" --alg "$DIGEST" --tsaurl "$TSURL" --tsmode RFC3161 "$tgt" 2>&1) || rc=$?;;
      digicertkeylocker) out=$("$TOOL_SMCTL" sign --keypair-alias "$PA1" --input "$tgt" 2>&1) || rc=$?;;
    esac
  fi
  if [ $rc -eq 0 ]; then
    hn=$(write_hashes "$tgt"); OKN=$((OKN+1)); say OK "signed: $(basename "$tgt")   -> ${hn// /, }"
    REPORT+=("{\"file\":\"$tgt\",\"kind\":\"$kind\",\"status\":\"signed\",\"message\":\"${msg//\"/\\\"}\"}")
  else
    FAILN=$((FAILN+1)); one=$(printf '%s' "$out" | tr '\n' ' ' | sed 's/  */ /g; s/"/'"'"'/g'); one=${one//$WORKPASS/***}
    say ERROR "FAILED: $tgt : $one"; REPORT+=("{\"file\":\"$tgt\",\"kind\":\"$kind\",\"status\":\"failed\",\"message\":\"$one\"}")
  fi
done

# ---- what happened
show_certificate "$PUBPEM"
repdir="${OUT_FOLDER:-$SCRIPT_DIR/transport}"; mkdir -p "$repdir"
rep="$repdir/sign-report_$(date +%Y%m%d-%H%M%S).json"
{ printf '{"version":"%s","time":"%s","timestamp":"%s","digest":"%s","provider":"%s","signed":%d,"skipped":%d,"failed":%d,"files":[' "$VERSION" "$(date -Is)" "$TSURL" "$DIGEST" "$PROVIDER" $OKN $SKN $FAILN
  (IFS=,; printf '%s' "${REPORT[*]:-}"); printf ']}\n'; } > "$rep"
say INFO "Report: $rep"
if [ $FAILN -gt 0 ]; then say ERROR "Signed $OKN, skipped $SKN, failed $FAILN (of ${#FILES[@]})."; else say OK "Signed $OKN, skipped $SKN, failed $FAILN (of ${#FILES[@]})."; fi
[ $CI = 1 ] && [ -n "${GITHUB_STEP_SUMMARY:-}" ] && printf '### Sign-Code\nSigned **%d**, skipped %d, failed **%d**. Timestamp %s\n' $OKN $SKN $FAILN "$TSURL" >> "$GITHUB_STEP_SUMMARY"
[ $CI = 1 ] && [ "$ENVKIND" = azure ] && echo "##vso[task.setvariable variable=SignCode.Signed]$OKN"
if [ $FAILN -gt 0 ]; then exit 6; fi
if [ $STRICT = 1 ] && [ $SKN -gt 0 ]; then say ERROR '--strict: some files were skipped.'; exit 6; fi
exit 0
